var FER_TN=[["01-01","Jour de l'An","رأس السنة الإدارية","New Year's Day"],["03-20","Fête de l'Indépendance","عيد الاستقلال","Independence Day"],["04-09","Journée des Martyrs","عيد الشهداء","Martyrs' Day"],["05-01","Fête du Travail","عيد الشغل","Labour Day"],["07-25","Fête de la République","عيد الجمهورية","Republic Day"],["08-13","Fête de la Femme","عيد المرأة","Women's Day"],["10-15","Fête de l'Évacuation","عيد الجلاء","Evacuation Day"],["12-17","Fête de la Révolution","عيد الثورة","Revolution Day"]];var FER_RELIG=[["Aïd el-Fitr (1er jour)","عيد الفطر (اليوم الأول)","Eid al-Fitr (day 1)"],["Aïd el-Fitr (2e jour)","عيد الفطر (اليوم الثاني)","Eid al-Fitr (day 2)"],["Aïd el-Idha (1er jour)","عيد الأضحى (اليوم الأول)","Eid al-Adha (day 1)"],["Aïd el-Idha (2e jour)","عيد الأضحى (اليوم الثاني)","Eid al-Adha (day 2)"],["Ras el Am el Hejri","رأس السنة الهجرية","Islamic New Year"],["Mouled","المولد النبوي الشريف","Mawlid"]];
function ferNom(f){return ui.lang==="ar"?f.nomAr||f.nom:ui.lang==="en"?f.nomEn||f.nom:f.nom||f.nomAr||""}function ferEtat(){if(!ui.fer)ui.fer={a:new Date().getFullYear(),d:"",nom:"",type:"paye",sites:[]};return ui.fer}function ferEcriture(){try{return accesMenu("feries")==="ecriture"}catch(e){return true}}
function viewFeries(){const F=ferEtat(),a=F.a,L=(db.feries||[]).filter(f=>f&&String(f.d).slice(0,4)===String(a)).sort((x,y)=>x.d<y.d?-1:x.d>y.d?1:0),ec=ferEcriture();const site=id=>(db.sites.find(x=>x.id===id)||{}).nom||id;const rows=L.map(f=>{const dt=new Date(+f.d.slice(0,4),+f.d.slice(5,7)-1,+f.d.slice(8,10));const repos=(db.cals||[]).length&&(db.cals||[]).every(c=>((c.hebdo||{})[(dt.getDay()+6)%7]||"repos")==="repos");return"<tr>"+'<td class="fw-mono">'+esc(dateAff(f.d))+"</td>"+'<td class="fw-sm">'+esc(t.days[(dt.getDay()+6)%7])+(repos?' <span class="fw-u-badge" title="'+esc(t.ferReposH)+'">'+esc(t.ferRepos)+"</span>":"")+"</td>"+"<td>"+esc(ferNom(f))+"</td>"+"<td>"+(ec?'<select data-ferf="type" data-id="'+esc(f.id)+'"><option value="paye"'+(f.type!=="non_paye"?" selected":"")+">"+esc(t.ferPaye)+'</option><option value="non_paye"'+(f.type==="non_paye"?" selected":"")+">"+esc(t.ferNonPaye)+"</option></select>":esc(f.type==="non_paye"?t.ferNonPaye:t.ferPaye))+"</td>"+'<td class="fw-sm">'+esc((f.sites||[]).length?(f.sites||[]).map(site).join(", "):t.ferTousSites)+"</td>"+"<td>"+(ec?'<button class="fw-btn sm" data-feract="del" data-id="'+esc(f.id)+'">'+esc(t.ferSuppr)+"</button>":"")+"</td></tr>"}).join("");const form=ec?'<div class="fw-card" style="padding:14px;margin-top:14px"><div class="fw-sec" style="margin-top:0">'+esc(t.ferAjout)+'</div><div class="fw-row2">'+field(t.ferDate,'<input type="date" id="ferD" value="'+esc(F.d||"")+'">')+field(t.ferLib,'<input type="text" id="ferNom" list="ferNomsL" value="'+esc(F.nom||"")+'" maxlength="80"><datalist id="ferNomsL">'+FER_RELIG.map(r=>'<option value="'+esc(ui.lang==="ar"?r[1]:ui.lang==="en"?r[2]:r[0])+'">').join("")+"</datalist>")+"</div>"+field(t.ferType,'<select id="ferType"><option value="paye">'+esc(t.ferPaye)+'</option><option value="non_paye">'+esc(t.ferNonPaye)+"</option></select>")+'<div class="fw-f"><label>'+esc(t.ferSites)+"</label>"+db.sites.map(x=>'<label class="fw-check"><input type="checkbox" data-fersite="'+esc(x.id)+'"><span>'+esc(x.nom)+"</span></label>").join("")+'<div class="fw-hint">'+esc(t.ferSitesH)+"</div></div>"+'<button class="fw-btn pri" data-feract="add">'+esc(t.ferAjouter)+"</button></div>":"";return hero({title:t.ferTitre,count:L.length,lede:t.ferLede,search:false})+'<div class="fw-toolbar"><button class="fw-btn sm" data-feract="prev">‹</button><span style="min-width:80px;text-align:center;font-weight:600">'+esc(String(a))+'</span><button class="fw-btn sm" data-feract="next">›</button><div class="fw-spacer"></div>'+(ec?'<button class="fw-btn pri" data-feract="tn">'+esc(t.ferTn.replace("{a}",a))+"</button>":"")+"</div>"+'<div class="fw-card"><table class="fw-tbl"><thead><tr><th>'+esc(t.ferDate)+"</th><th>"+esc(t.ferJour)+"</th><th>"+esc(t.ferLib)+"</th><th>"+esc(t.ferType)+"</th><th>"+esc(t.ferSites)+"</th><th></th></tr></thead><tbody>"+(rows||'<tr><td colspan="6"><div class="fw-empty"><strong>'+esc(t.emptyT)+"</strong>"+esc(t.ferVide.replace("{a}",a))+"</div></td></tr>")+"</tbody></table></div>"+form+'<div class="fw-note">'+esc(t.ferNote)+"</div>"}
VIEWS.feries=viewFeries;ECRAN_DROIT.feries="CAL";
document.addEventListener("click",ev=>{const el=ev.target&&ev.target.closest?ev.target.closest("[data-feract]"):null;if(!el)return;const F=ferEtat(),act=el.dataset.feract;if(act==="prev"||act==="next"){F.a+=act==="prev"?-1:1;return render()}if(!ferEcriture()){flash(t.ferLecture,"warn");return}if(!Array.isArray(db.feries))db.feries=[];if(act==="tn"){let n=0;FER_TN.forEach(x=>{const d=F.a+"-"+x[0];if(!db.feries.some(f=>f.d===d&&!(f.sites||[]).length)){db.feries.push({id:uid("fe"),d,nom:x[1],nomAr:x[2],nomEn:x[3],type:"paye",sites:[]});n++}});save();flash(t.ferTnOk.replace("{n}",n).replace("{a}",F.a),"ok");return render()}if(act==="add"){const d=(document.getElementById("ferD")||{}).value||"",nom=String((document.getElementById("ferNom")||{}).value||"").trim(),type=(document.getElementById("ferType")||{}).value==="non_paye"?"non_paye":"paye",sites=Array.from(document.querySelectorAll("[data-fersite]")).filter(x=>x.checked).map(x=>x.dataset.fersite);if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!nom){flash(t.ferReq,"warn");return}const r=FER_RELIG.find(x=>x.indexOf(nom)>=0);db.feries.push({id:uid("fe"),d,nom:r?r[0]:nom,nomAr:r?r[1]:"",nomEn:r?r[2]:"",type,sites});F.a=+d.slice(0,4);save();flash(t.ferAjoute.replace("{d}",dateAff(d)),"ok");return render()}if(act==="del"){const f=db.feries.find(x=>x.id===el.dataset.id);if(!f)return;fwConfirm({message:t.ferSupprConf.replace("{n}",ferNom(f)+" — "+dateAff(f.d))},function(ok){if(!ok)return;db.feries=db.feries.filter(x=>x.id!==f.id);save();render()});return}});
document.addEventListener("change",ev=>{const el=ev.target;if(!el||!el.dataset||el.dataset.ferf!=="type")return;if(!ferEcriture())return;const f=(db.feries||[]).find(x=>x.id===el.dataset.id);if(!f)return;f.type=el.value==="non_paye"?"non_paye":"paye";save();render()});
Object.assign(T.fr,{ferTitre:"Jours fériés",ferLede:"Une seule liste pour toute l'entreprise : chaque jour férié s'applique automatiquement à tous les calendriers (ou aux sites choisis). Un jour férié qui tombe un jour de repos est écarté. Une exception posée dans un calendrier reste prioritaire.",ferTn:"Jours fériés tunisiens {a}",ferTnOk:"{n} jour(s) férié(s) ajouté(s) pour {a}. Ajoutez les fêtes religieuses (dates variables) avec le formulaire.",ferDate:"Date",ferJour:"Jour",ferLib:"Libellé",ferType:"Type",ferPaye:"Chômé payé",ferNonPaye:"Chômé non payé",ferSites:"Sites",ferTousSites:"Tous les sites",ferSitesH:"Aucun site coché = tous les sites.",ferSuppr:"Supprimer",ferSupprConf:"Supprimer le jour férié « {n} » ?",ferAjout:"Ajouter un jour férié",ferAjouter:"Ajouter",ferAjoute:"Jour férié du {d} ajouté.",ferReq:"Date et libellé obligatoires.",ferVide:"Aucun jour férié pour {a}.",ferRepos:"jour de repos",ferReposH:"Tombe un jour de repos dans tous les calendriers : écarté du calcul.",ferLecture:"Modification réservée au paramétrage des calendriers.",ferNote:"Calcul : un jour férié chômé payé alimente HFERIEPAY (durée de la journée prévue) ; travaillé, il alimente HFERIE (et sa majoration) mais pas les heures supplémentaires, sauf règle « Férié travaillé compté aussi en heures sup. ». Jours fériés à date fixe : ajoutés automatiquement pour l'année en cours et la suivante (un jour supprimé n'est pas recréé). Fêtes religieuses : saisissez leur date officielle chaque année (rappel dans « À traiter »)."});
Object.assign(T.en,{ferTitre:"Public holidays",ferLede:"One list for the whole company: each public holiday applies automatically to every calendar (or to the chosen sites). A holiday falling on a rest day is ignored. An exception set in a calendar still prevails.",ferTn:"Tunisian public holidays {a}",ferTnOk:"{n} public holiday(s) added for {a}. Add the religious holidays (variable dates) with the form.",ferDate:"Date",ferJour:"Day",ferLib:"Label",ferType:"Type",ferPaye:"Paid day off",ferNonPaye:"Unpaid day off",ferSites:"Sites",ferTousSites:"All sites",ferSitesH:"No site ticked = all sites.",ferSuppr:"Delete",ferSupprConf:"Delete the public holiday « {n} »?",ferAjout:"Add a public holiday",ferAjouter:"Add",ferAjoute:"Public holiday on {d} added.",ferReq:"Date and label are required.",ferVide:"No public holiday for {a}.",ferRepos:"rest day",ferReposH:"Falls on a rest day in every calendar: ignored.",ferLecture:"Changes are restricted to calendar settings.",ferNote:"Calculation: a paid holiday off feeds HFERIEPAY (planned day length); worked, it feeds HFERIE (and its premium) but not overtime, unless the rule « Holiday work also counted as overtime » is set. Fixed-date holidays: added automatically for the current and next year (a deleted day is not recreated). Religious holidays: enter their official date every year (reminder in “To do”)."});
Object.assign(T.ar,{ferTitre:"الأعياد والعطل الرسمية",ferLede:"قائمة واحدة لكامل المؤسسة: كل عيد يُطبَّق آليا على كل الرزنامات (أو على المواقع المختارة). العيد الذي يوافق يوم راحة لا يُحتسب. الاستثناء المضبوط في رزنامة يبقى أولويا.",ferTn:"الأعياد التونسية {a}",ferTnOk:"أُضيف {n} عيد لسنة {a}. أضف الأعياد الدينية (تواريخ متغيرة) عبر الاستمارة.",ferDate:"التاريخ",ferJour:"اليوم",ferLib:"التسمية",ferType:"النوع",ferPaye:"عطلة مدفوعة",ferNonPaye:"عطلة غير مدفوعة",ferSites:"المواقع",ferTousSites:"كل المواقع",ferSitesH:"دون اختيار = كل المواقع.",ferSuppr:"حذف",ferSupprConf:"حذف العيد « {n} »؟",ferAjout:"إضافة عيد",ferAjouter:"إضافة",ferAjoute:"أُضيف عيد {d}.",ferReq:"التاريخ والتسمية إجباريان.",ferVide:"لا أعياد لسنة {a}.",ferRepos:"يوم راحة",ferReposH:"يوافق يوم راحة في كل الرزنامات: لا يُحتسب.",ferLecture:"التعديل مخصص لضبط الرزنامات.",ferNote:"الاحتساب: العيد المدفوع غير المعمول يُغذّي HFERIEPAY (مدة اليوم المبرمج)؛ وإن عُمل فيه يُغذّي HFERIE وزيادتها دون الساعات الإضافية، إلا إذا فُعّلت قاعدة «احتساب العمل يوم العيد ساعات إضافية أيضا». العطل ذات التاريخ الثابت: تُضاف آليا للسنة الحالية والموالية (اليوم المحذوف لا يُعاد إنشاؤه). الأعياد الدينية: أدخل تاريخها الرسمي كل سنة (تذكير في « للمعالجة »)."});
/* styles de l'assistant intégrés : affichage correct même si app.css n'a pas été mis à jour */
