function fmClair(n,D){const v=x=>fmClair(x,D);if(!n)return"";switch(n.k){case"num":return String(n.v).replace(".",",");case"var":return"« "+(D.get(n.v)||n.v)+" »";case"neg":return"− "+v(n.a);case"bin":{const o={"+":"+","-":"−","*":"×","/":"÷","=":t.fmEgal,"<>":t.fmDiff,"<":"<",">":">","<=":"≤",">=":"≥",ET:t.fmEt,OU:t.fmOu}[n.op]||n.op;return v(n.a)+" "+o+" "+v(n.b)}case"fn":{const a=n.args.map(v);switch(n.name){case"SI":return t.fmSi.replace("{c}",a[0]).replace("{a}",a[1]).replace("{b}",a[2]);case"MIN":return t.fmMin.replace("{l}",a.join(" ; "));case"MAX":return t.fmMax.replace("{l}",a.join(" ; "));case"CUM":return t.fmCumL.replace("{c}",a[0]);case"ARRONDI":return t.fmArrondi.replace("{a}",a[0]).replace("{n}",a[1]);case"NON":return t.fmNon.replace("{a}",a[0]);case"ET":return"("+a.join(" "+t.fmEt+" ")+")";case"OU":return"("+a.join(" "+t.fmOu+" ")+")";default:return n.name+"("+a.join(" ; ")+")"}}}return""}
