function fmPaletteHtml(a){const D=fmDesc(),K=fmConnus(a.code),vus=new Set;const chip=(ins,lib,tit,cls)=>'<button type="button" class="fw-fm-chip'+(cls?" "+cls:"")+'" data-fmins="'+esc(ins)+'" title="'+esc(tit||"")+'">'+esc(lib)+"</button>";let h="";FM_CATS.forEach(c=>{const l=c[1].filter(x=>K.vars.has(x));l.forEach(x=>vus.add(x));if(l.length)h+='<div class="fw-fm-cat"><div class="fw-fm-catl">'+esc(t[c[0]])+"</div>"+l.map(x=>chip(x,x,D.get(x))).join("")+"</div>"});const tt=(db.tt||[]).map(x=>ttVar(x)).filter(x=>K.vars.has(x)&&!vus.has(x));tt.forEach(x=>vus.add(x));if(tt.length)h+='<div class="fw-fm-cat"><div class="fw-fm-catl">'+esc(t.fmCatTt)+"</div>"+tt.map(x=>chip(x,x,D.get(x))).join("")+"</div>";const cp=Array.from(K.cpt);if(cp.length)h+='<div class="fw-fm-cat"><div class="fw-fm-catl">'+esc(t.fmCatCpt)+'</div><div class="fw-hint" style="margin:0 0 6px">'+esc(t.fmCptH)+"</div>"+cp.map(x=>chip(x,x,D.get(x),"alt")+chip("CUM("+x+")","CUM("+x+")",t.fmCumL.replace("{c}",D.get(x)||x),"alt")).join("")+"</div>";const autres=Array.from(K.vars).filter(x=>!vus.has(x)&&!K.cpt.has(x)&&x.indexOf("AJ_")!==0);if(autres.length)h+='<div class="fw-fm-cat"><div class="fw-fm-catl">'+esc(t.fmCatAutres)+"</div>"+autres.map(x=>chip(x,x,D.get(x))).join("")+"</div>";h+='<div class="fw-fm-cat"><div class="fw-fm-catl">'+esc(t.fmCatFn)+"</div>"+FM_FN.map(f=>chip(f[0]+"()",f[1],t.fmExemple+" "+f[2],"fn")).join("")+'<div class="fw-hint" style="margin-top:6px">'+esc(t.fmOps)+"</div></div>";return'<div class="fw-fm-pal">'+h+"</div>"}
