/* 56.33.11 : période « Du / au » — dans tous les écrans, une date de début postérieure à la date de fin est refusée : message, champ signalé et valeur précédente rétablie (couples d'attributs du/au, from/to, valid_from/valid_to, debut/fin, ou identifiants …Du/…Au) */
var PER_COUPLES=[["du","au"],["from","to"],["valid_from","valid_to"],["debut","fin"]];
function perPartenaire(inp){const attrs=Array.prototype.filter.call(inp.attributes,a=>/^data-/.test(a.name)&&a.name!=="data-jj");for(const a of attrs){for(const c of PER_COUPLES){const i=c.indexOf(a.value);if(i<0)continue;const autre=c[1-i];const autres=attrs.filter(x=>x!==a&&!/^data-fw/.test(x.name));let n=inp.parentElement;for(let k=0;k<6&&n;k++,n=n.parentElement){const cand=Array.prototype.find.call(n.querySelectorAll('input[type="date"]['+a.name+'="'+autre+'"]'),x=>x!==inp&&autres.every(z=>x.getAttribute(z.name)===z.value));if(cand)return{autre:cand,debut:i===0}}}}const m=/^(.*)(Du|Au)$/.exec(inp.id||"");if(m){const x=document.getElementById(m[1]+(m[2]==="Du"?"Au":"Du"));if(x&&x.type==="date")return{autre:x,debut:m[2]==="Du"}}return null}
function perControle(ev){const inp=ev.target;if(!inp||inp.type!=="date"||!inp.value)return;if(+inp.value.slice(0,4)<1900)return;const p=perPartenaire(inp);if(!p||!p.autre.value||+p.autre.value.slice(0,4)<1900){inp.dataset.fwPrec=inp.value;return}const du=p.debut?inp.value:p.autre.value,au=p.debut?p.autre.value:inp.value;if(du<=au){inp.dataset.fwPrec=inp.value;return}if(p.debut&&inp.closest&&inp.closest(".fw-dmdpanel"))return;/* (formulaire de demande : géré par dmdDateSuit, qui garde le mode « plage ») *//* 56.33.11 : date de DÉBUT placée après la fin (saisie naturelle d'une période future : début d'abord) → la date de fin suit la date de début au lieu de refuser la saisie (le refus faisait garder l'ancienne date de début, sans que l'on s'en aperçoive) ; une date de FIN avant le début reste refusée */if(p.debut){const b=p.autre;b.value=inp.value;b.dataset.fwPrec=b.value;inp.dataset.fwPrec=inp.value;const tb=b.parentElement&&b.parentElement.querySelector(".fw-jj-txt");if(tb)tb.value=dateAff(b.value);try{b.dispatchEvent(new Event("input",{bubbles:true}));b.dispatchEvent(new Event("change",{bubbles:true}))}catch(e){}if(ev.type==="change"||inp.dataset.fwSignale!==inp.value){inp.dataset.fwSignale=inp.value;try{flash(t.perFinSuit.replace("{f}",dateAff(inp.value)),"info")}catch(e){}}return}ev.stopImmediatePropagation();ev.preventDefault();const prec=inp.dataset.fwPrec!==undefined?inp.dataset.fwPrec:inp.defaultValue;const essai=inp.value;inp.value=prec&&!(p.debut?prec>au:prec<du)?prec:"";const txt=inp.parentElement&&inp.parentElement.querySelector(".fw-jj-txt");[inp,txt,p.autre,p.autre.parentElement&&p.autre.parentElement.querySelector(".fw-jj-txt")].forEach(x=>{if(x){x.classList.add("err");x.setAttribute("aria-invalid","true");setTimeout(()=>{x.classList.remove("err");x.removeAttribute("aria-invalid")},4000)}});if(txt)txt.value=inp.value?dateAff(inp.value):"";if(ev.type==="change"||!inp.dataset.fwSignale||inp.dataset.fwSignale!==essai){inp.dataset.fwSignale=essai;try{flash((p.debut?t.perDebutApres:t.perFinAvant).replace("{d}",dateAff(du)).replace("{f}",dateAff(au)),"err")}catch(e){}}}
if(typeof document!=="undefined"&&document.addEventListener){document.addEventListener("input",perControle,true);document.addEventListener("change",perControle,true)}
Object.assign(T.fr,{perFinSuit:"Date de fin reportée au {f} (elle précédait la nouvelle date de début).",perDebutApres:"Période impossible : la date de début ({d}) est après la date de fin ({f}). Choisissez une date de début antérieure ou égale, ou modifiez d'abord la date de fin.",perFinAvant:"Période impossible : la date de fin ({f}) est avant la date de début ({d}). Choisissez une date de fin postérieure ou égale, ou modifiez d'abord la date de début."});
Object.assign(T.en,{perFinSuit:"End date moved to {f} (it was before the new start date).",perDebutApres:"Invalid period: the start date ({d}) is after the end date ({f}). Pick an earlier or equal start date, or change the end date first.",perFinAvant:"Invalid period: the end date ({f}) is before the start date ({d}). Pick a later or equal end date, or change the start date first."});
Object.assign(T.ar,{perFinSuit:"نُقل تاريخ النهاية إلى {f} (كان قبل تاريخ البداية الجديد).",perDebutApres:"فترة غير ممكنة: تاريخ البداية ({d}) بعد تاريخ النهاية ({f}). اختر تاريخ بداية سابقا أو مساويا، أو عدّل تاريخ النهاية أولا.",perFinAvant:"فترة غير ممكنة: تاريخ النهاية ({f}) قبل تاريخ البداية ({d}). اختر تاريخ نهاية لاحقا أو مساويا، أو عدّل تاريخ البداية أولا."});
/* 56.33.11 — audit RH › Employés (grand effectif : annuaire servi par le serveur, salariés non chargés dans le navigateur).
   Unicité du matricule, du badge et du CIN vérifiée sur tout le personnel avant l'enregistrement (et imposée par le
   serveur) ; responsable et équipe lus sur le serveur ; exports « Export des données » et « sélection » complets. */
function annuSrv(){return typeof ANNUAIRE_PAGINE!=="undefined"&&!!ANNUAIRE_PAGINE&&!DEMO&&!!SESS}
function UNI_MSG(k){return({mat:t.vDoublonMat,badge:t.vDoublonBadge,cin:t.vDoublonCin})[k]||t.vDoublonMat}
function champErreursPremier(ent,row){const e=champErreurs(ent,row);return Object.keys(e)[0]||""}
function empUniCle(r){return JSON.stringify([r.id,String(r.mat||"").trim(),String(r.badge||"").trim(),String(r.cin||"").trim()])}
function empUniVerifier(row,reprise){if(!annuSrv())return true;const k=empUniCle(row);if(ui.uniOk===k){ui.uniOk=null;return true}if(ui.uniEnCours)return false;ui.uniEnCours=true;
 fetch("api/v1/employes/unicite",{method:"POST",credentials:"same-origin",cache:"no-store",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:row.id,mat:row.mat,badge:row.badge,cin:row.cin})})
 .then(r=>{if(r.status===401){apiSessionPerdue();throw new Error("session")}return r.ok?r.json():{conflits:[]}}).then(j=>{ui.uniEnCours=false;const c=j.conflits||[];
  if(c.length){ui.uniErr={id:row.id,c:{}};c.forEach(x=>{ui.uniErr.c[x.champ]=x.valeur});const k0=c[0].champ;if(ui.tiroirEdit)ui.tiroirTab=TIROIR_CHAMP_ONGLET[k0]||ui.tiroirTab;flash(UNI_MSG(k0)+" : « "+c[0].valeur+" »","err");render();return}
  ui.uniErr=null;ui.uniOk=k;reprise()}).catch(e=>{ui.uniEnCours=false;if(e.message!=="session")flash(t.svcErreur,"err")});return false}
/* enregistrement refusé par le serveur (valeur déjà attribuée) : la fiche reprend la version du serveur */
function empRefusTraiter(l){const m=SYNC&&SYNC.colls&&SYNC.colls.emps;l.forEach(x=>{const i=(db.emps||[]).findIndex(e=>String(e.id)===String(x.id));if(i<0)return;const ancien=m&&m.get(String(x.id));if(ancien){try{db.emps[i]=JSON.parse(ancien)}catch(e){}}else db.emps.splice(i,1)});
 try{normalize()}catch(e){}try{annuInvalider()}catch(e){}if(Date.now()>IMP_SILENCE)flash(l[0].champ?UNI_MSG(l[0].champ)+" : « "+l[0].valeur+" » — "+t.uniRefusSrv:t.srvRefusMotif.replace("{m}",l[0].message||""),"err");render()}
/* nom d'un salarié non chargé (responsable…) : lu une fois sur le serveur */
const NOM_DEMANDES=new Set;
function empNomCharger(mat){mat=String(mat||"");if(!mat||!annuSrv()||NOM_DEMANDES.has(mat))return null;NOM_DEMANDES.add(mat);
 fetch("api/v1/employes/lot",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({mats:[mat]})}).then(r=>r.ok?r.json():{lignes:[]}).then(j=>{if((j.lignes||[]).length){nomsRetenir(j.lignes);render()}}).catch(()=>{});return null}
/* équipe (salariés dont il est le responsable) et collègues (même responsable) : comptés sur le serveur */
const EQUIPE_SRV=new Map;
function empEquipe(e){const loc=()=>{const chef=e.chefMat?(db.emps||[]).find(x=>x.mat===e.chefMat):null;return{equipe:(db.emps||[]).filter(x=>!x.sortie&&x.chefMat===e.mat).length,collegues:chef?(db.emps||[]).filter(x=>!x.sortie&&x.chefMat===chef.mat&&x.id!==e.id).length:0}};
 if(!annuSrv())return loc();const k=e.mat+"|"+(e.chefMat||"");const c=EQUIPE_SRV.get(k);if(c&&Date.now()-c.t<60000)return c;
 if(!c||!c.enCours){const n=mat=>mat?fetch("api/v1/employes?limit=1&statut=actifs&chef="+encodeURIComponent(mat),{credentials:"same-origin",cache:"no-store"}).then(r=>r.ok?r.json():{total:0}).then(j=>+j.total||0):Promise.resolve(0);
  EQUIPE_SRV.set(k,Object.assign({equipe:0,collegues:0},c||{},{enCours:true,t:c?c.t:0}));
  Promise.all([n(e.mat),n(e.chefMat)]).then(([a,b])=>{EQUIPE_SRV.set(k,{equipe:a,collegues:Math.max(0,b-(estActif(e)?1:0)),t:Date.now()});render()}).catch(()=>EQUIPE_SRV.delete(k))}
 return EQUIPE_SRV.get(k)}
/* fiches complètes depuis le serveur (sans photo), par lots de 1 000 */
async function empFichesServeur(mats){const fiches=new Map;for(let i=0;i<mats.length;i+=1000){const x=await fetch("api/v1/employes/complets",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({mats:mats.slice(i,i+1000),sansPhoto:true})});if(x.status===401){apiSessionPerdue();throw new Error("session")}if(!x.ok)throw new Error("HTTP "+x.status);((await x.json()).lignes||[]).forEach(e=>fiches.set(String(e.mat),e))}return mats.map(m=>fiches.get(m)).filter(Boolean)}
/* « Export des données » (fiche des employés) : tous les salariés de la liste affichée (mêmes filtres), pas seulement la page */
async function exportEmployesServeur(){const s=ui.annu||{q:"",statut:"actifs"},F=annuFiltres(s);flash(t.chargement);
 const r=await exportServeurPages((off,lim)=>fetch("api/v1/employes?limit="+lim+"&offset="+off+"&statut="+encodeURIComponent(F.statut||"")+"&site="+encodeURIComponent(F.site)+"&dept="+encodeURIComponent(F.dept)+"&q="+encodeURIComponent(F.q),{credentials:"same-origin",cache:"no-store"}).then(x=>{if(!x.ok)throw new Error("HTTP "+x.status);return x.json()}).then(j=>({total:j.total,items:j.lignes||[]})),500);
 const l=await empFichesServeur(r.lignes.map(e=>String(e.mat)));if(!l.length){flash(t.expNoData||t.emptyT,"warn");return}
 const cols=["ID","NAME","NAMEEMPLOYEE","LASTNAME","EMPLOYEECODE","DEPARTMENTS","ACTIVEDAYS","CARDS","EMAIL","PHONE","CALENDAR","SITE","PORTAL.USAPORTAL"];const lines=[csvLine(cols)];
 l.forEach(e=>{lines.push(csvLine([e.id,e.cin,e.prenom,e.nom,e.mat,deptPath(e.deptId).split(" / ").join("/"),(e.entree||"")+"/"+(e.sortie||""),e.badge,e.email,e.tel,calNomAt(e,todayKey()),siteName(e.siteId),e.portail?"1":"0"]))});
 download("employes_"+(new Date).toISOString().slice(0,10)+".csv",lines.join("\r\n"));flash(t.exported+" ("+l.length+")","ok");if(r.total>l.length)flash(t.expLimite.replace("{n}",l.length).replace("{t}",r.total),"warn")}
/* export de la sélection : salariés cochés sur toutes les pages (fiches lues sur le serveur) */
async function bulkExportEmpServeur(ids){const mats=ids.map(id=>{const e=empVueId(id);return e&&e.mat?String(e.mat):""}).filter(Boolean);const l=await empFichesServeur(mats);if(!l.length){flash(t.expNoData||t.emptyT,"warn");return}
 const headers=["MATRICULE","NOM","PRENOM","CIN","SITE","DEPARTEMENT","ENTREE","SORTIE","EMAIL","TEL","BADGE","PORTAIL"];
 const rows=l.map(e=>[e.mat,e.nom,e.prenom,e.cin,siteName(e.siteId),deptPath(e.deptId),dateAff(e.entree||""),dateAff(e.sortie||""),e.email,e.tel,e.badge,e.portail?1:0]);
 download("FIWAKTI_selection_employes_"+todayKey()+".csv",[csvLine(headers)].concat(rows.map(csvLine)).join("\r\n"));flash(t.bulkExport+" ("+rows.length+")","ok")}
