/* nombre décimal affiché selon la langue (20,5 en français et en arabe, 20.5 en anglais), deux décimales au plus */
function nbDec(v){const n=Number(v);if(!isFinite(n))return String(v);const x=String(Math.round(n*100)/100);return t===T.en?x:x.replace(".",",")}
/* 56.33.11 — notifications de l'employé. Les messages des demandes (acceptée, refusée, rectifiée, niveau franchi, à
   valider) étaient créés mais affichés nulle part : ils apparaissent dans la cloche et dans le portail, avec « non lu ».
   L'e-mail correspondant est envoyé par le serveur (adresse de la fiche du salarié) si l'envoi est configuré. */
function mesNotifs(){const e=typeof monEmploye==="function"?monEmploye():null;if(!e)return[];return(db.notifs||[]).filter(n=>n&&String(n.mat)===String(e.mat)&&n.txt).sort((a,b)=>String(b.ts||b.d||"").localeCompare(String(a.ts||a.d||"")))}
function mesNotifsHtml(max,cloche){const l=mesNotifs();if(!l.length)return cloche?"":'<div class="fw-card" style="margin-top:14px"><div class="fw-cardh">'+esc(t.ntfMes)+'</div><div class="fw-empty">'+esc(t.ntfMesVide)+"</div></div>";
 const nl=l.filter(n=>!n.lu).length;
 const ligne=n=>'<button type="button" class="fw-ntfi '+(n.lu?"vu":"w")+'" data-act="ntf-msg" data-id="'+esc(n.id)+'"><span class="ic">'+ntfIco("✓")+'</span><span>'+esc(ntfTexte(n))+'<br><span class="fw-muted fw-sm">'+esc(dateAff(String(n.ts||n.d||"").slice(0,16)))+"</span></span>"+(n.lu?"":'<span class="fw-ntfnew">'+esc(t.ntfNouveau)+"</span>")+"</button>";
 const tete=esc(t.ntfMes)+(nl?" ("+nl+")":"")+(nl?'<button type="button" class="fw-ntf-tout" data-act="ntf-msg-tout">'+esc(t.ntfToutVu)+"</button>":"");
 if(cloche)return'<div class="fw-ntf-sec">'+tete+"</div>"+l.slice(0,max).map(ligne).join("");
 return'<div class="fw-card" style="margin-top:14px"><div class="fw-cardh">'+tete+'</div><div class="fw-wb">'+l.slice(0,max).map(ligne).join("")+"</div></div>"}
document.addEventListener("click",ev=>{const b=ev.target&&ev.target.closest?ev.target.closest('[data-act="ntf-msg"],[data-act="ntf-msg-tout"]'):null;if(!b)return;ev.preventDefault();ev.stopPropagation();
 const l=b.dataset.act==="ntf-msg-tout"?mesNotifs().filter(n=>!n.lu):mesNotifs().filter(n=>n.id===b.dataset.id&&!n.lu);
 if(l.length){l.forEach(n=>{n.lu=true;n.luLe=maintenantStamp()});try{save()}catch(e){}}
 if(b.dataset.act==="ntf-msg"&&typeof ecranAutorise==="function"&&ecranAutorise("portal")&&ui.view!=="portal"){ui.ntfOpen=false;ui.view="portal"}render()},true);
/* réglages d'envoi : mot de passe gardé chiffré par le serveur, activation des e-mails de notification, vrai test */
let SMTP_ETAT={charge:false,mdpDefini:false,dernier:null};
function smtpEtatCharger(){if(SMTP_ETAT.charge||DEMO||!SESS)return;SMTP_ETAT.charge=true;fetch("api/v1/systeme/courriel",{credentials:"same-origin",cache:"no-store"}).then(r=>r.ok?r.json():null).then(j=>{if(j){SMTP_ETAT.mdpDefini=!!j.mdpDefini;SMTP_ETAT.dernier=j.dernier;render()}}).catch(()=>{})}
function smtpMdpHtml(){smtpEtatCharger();return field(t.smtpMdp,'<div class="fw-u-row" style="gap:8px"><input type="password" data-smtpmdp="1" autocomplete="new-password" placeholder="'+esc(SMTP_ETAT.mdpDefini?t.smtpMdpDefini:t.smtpMdpVide)+'" style="flex:1"><button type="button" class="fw-btn sm" data-act="smtp-mdp">'+esc(t.save)+"</button></div>",t.smtpMdpH)}
