/* 56.33.11 — Suivi des équipes & présences en grand effectif : onglets « Pointages & présences » et « Annuaire &
   profils » servis par le serveur (statuts, comptes et listes sur tout le périmètre, page par page). Ils ne portaient
   que sur les salariés chargés dans le navigateur (une cinquantaine). */
function suiviSrv(){return typeof GRAND!=="undefined"&&!!GRAND&&!DEMO&&!!SESS}
let SPRES={cle:"",data:null,enCours:false,erreur:""},SANNU={cle:"",data:null,enCours:false,erreur:""};
function suiviCharger(etat,cle,url,apres){if(etat.cle===cle||etat.enCours)return;etat.enCours=true;const c0=cle;
 fetch(url,{credentials:"same-origin",cache:"no-store"}).then(r=>{if(r.status===401){apiSessionPerdue();throw new Error("session")}return r.json().then(j=>{if(!r.ok)throw new Error(j.message||j.erreur||"HTTP "+r.status);return j})})
 .then(j=>{etat.enCours=false;etat.cle=c0;etat.data=j;etat.erreur="";try{apres&&apres(j)}catch(e){}if(j&&j.recalcul)setTimeout(()=>{etat.cle="";render()},3000);render()})
 .catch(e=>{etat.enCours=false;etat.cle=c0;etat.erreur=e.message;render()})}
function suiviParams(o){return Object.keys(o).filter(k=>o[k]!==""&&o[k]!=null).map(k=>k+"="+encodeURIComponent(o[k])).join("&")}
function suiviOngletPtgSrv(dr){const s=sEtat(),auj=todayKey();let du=auj,au=auj;if(s.date==="hier"){du=au=dAjout(auj,-1)}else if(s.date==="sem"){du=lundiDe(auj)}
 const q=(ui.q||"").trim();const o={du,au,statut:s.statut||"",dept:s.dept||"",chef:s.chef||"",site:ui.siteFilter||"",q:q.length>=2?q:"",limit:s.limPtg||60};
 const cle=suiviParams(o)+"|"+suiviVersion();suiviCharger(SPRES,cle,"api/v1/calcul/presences?"+suiviParams(o),j=>nomsRetenir((j.items||[]).map(x=>x.e)));
 const d=SPRES.data||{},c=d.compte||{};const n=k=>c[k]||0;
 const statuts=[["",t.chTous],["present",t.stPresents+" "+(n("present")+n("retard")+n("incomplet"))],["retard",t.stRetards+" "+n("retard")],["absent",t.stAbsents+" "+n("absent")],["conge",t.stConges+" "+n("conge")],["incomplet",t.stIncomplets+" "+n("incomplet")]];
 const tete='<div class="fw-inbox-hd">'+seg([["auj",t.ptgAuj],["hier",t.sHier],["sem",t.sSemaine]],"s-date","data-sdt",s.date)+seg(statuts,"s-statut","data-sst",s.statut)+'<div class="fw-spacer"></div>'+suiviFiltresHTML(false)+"</div>"+(q.length===1?'<div class="fw-hint" style="margin:-6px 0 10px">'+esc(t.sDeuxLettres)+"</div>":"");
 if(SPRES.erreur&&SPRES.cle===cle)return tete+'<div class="fw-card"><div class="fw-empty"><strong>'+esc(t.svcErreur)+"</strong>"+esc(SPRES.erreur)+"</div></div>";
 if(!SPRES.data||SPRES.cle!==cle&&!SPRES.data.items)return tete+'<div class="fw-hint" aria-busy="true" style="padding:24px">'+esc(t.grandCalcul)+"</div>";
 const rows=(d.items||[]).map(it=>{const jour=(db.jours||[]).find(x=>x.id===it.jid)||null;const list=(it.mv||[]).map(m=>({id:m[0],ts:it.d+" "+m[1]+(m[6]||":00"),sens:m[2],dev:m[3],src:m[4]}));
  let st={c:it.st,l:""};if(it.st==="present")st.l=t.stPresent;else if(it.st==="retard")st.l=t.stRetard+" · "+fmtMin(it.ret||0);else if(it.st==="incomplet")st.l=t.stIncomplet;else if(it.st==="conge")st.l=it.abs||t.stConge;else if(it.st==="repos")st.l=it.jid==="ferie"?t.holiday:t.rest;
  else{st.l=t.stAbsent;if(it.d===auj&&jour){const h=new Date,deb=toMin(debutJour(jour)||"00:00")+(jour.tolIn||0);if(h.getHours()*60+h.getMinutes()<deb)st={c:"attendu",l:t.stAttendu}}}
  return{e:it.e||{mat:it.mat},k:it.d,inf:{jid:it.jid,jour,reel:it.reel},d:{HP:it.hp,RET:it.ret},list,st}});
 const ligne=r=>{const e=r.e,j=r.inf.jour,list=r.list;const ent=list.find(m=>m.sens==="E");const der=list.length>=2?list[list.length-1]:null;const sortie=der&&der.sens==="S"?String(der.ts).slice(11,16):"—";
  const pill='<span class="fw-st '+r.st.c+'">'+esc(r.st.c==="present"?t.stOk:r.st.l)+"</span>";
  return'<tr class="fw-srow" data-act="tiroir" data-tid="'+esc(e.id)+'">'+'<td><div class="fw-empcell">'+empAvatar(e,30)+"<div><strong>"+esc((e.prenom||"")+" "+(e.nom||""))+"</strong>"+"<span>"+esc([e.grade,s.date==="sem"?fmtJour(r.k):""].filter(Boolean).join(" · ")||e.mat)+"</span></div></div></td>"
  +'<td class="fw-sm">'+(r.inf.jid==="repos"?esc(t.rest):r.inf.jid==="ferie"?esc(t.holiday):esc(horaireJour(j)||"—"))+"</td>"+'<td class="fw-mono">'+esc(ent?String(ent.ts).slice(11,16):"—")+"</td>"+'<td class="fw-mono">'+esc(sortie)+"</td>"
  +'<td class="fw-num fw-mono">'+esc(r.d.HP==null?"—":hh(r.d.HP))+"</td>"+"<td>"+pill+' <button type="button" class="fw-btn sm ghost" data-act="tiroir" data-tid="'+esc(e.id)+'">'+esc(t.sDetails)+"</button>"
  +' <button type="button" class="fw-btn sm" data-act="pj-ouvrir" data-mat="'+esc(e.mat)+'" data-d="'+esc(r.k)+'">'+esc(t.pjVoirModifier)+"</button></td></tr>"};
 const reste=(d.total||0)-rows.length;
 const table=rows.length?'<div class="fw-card"><div class="fw-tbl-wrap"><table class="fw-tbl fw-stbl"><thead><tr><th>'+esc(t.emp)+"</th><th>"+esc(t.sHoraire)+"</th><th>"+esc(t.sEntree)+"</th><th>"+esc(t.sSortie)+'</th><th class="fw-num">'+esc(t.sTotal)+"</th><th>"+esc(t.statut)+"</th></tr></thead><tbody>"+rows.map(ligne).join("")+"</tbody></table></div></div>"
  +(reste>0?'<button type="button" class="fw-btn fw-plus" data-act="s-plus" data-sk="limPtg">'+esc(t.sPlus.replace("{n}",reste))+"</button>":""):'<div class="fw-card"><div class="fw-empty"><strong>'+esc(t.emptyT)+"</strong>"+esc(t.noMatch)+"</div></div>";
 return tete+(SPRES.cle!==cle?'<div class="fw-hint" aria-busy="true">'+esc(t.chargement)+"</div>":"")+table}
function suiviOngletAnnuaireSrv(dr){const s=sEtat(),q=(ui.q||"").trim();const depts=s.dept?Array.from(deptDescendants(s.dept)).join(","):"";
 const o={limit:s.limAnnu||60,offset:0,statut:s.sortis?"":"actifs",site:ui.siteFilter||"",dept:depts,chef:s.chef||"",contrat:s.contrat||"",q:q.length>=2?q:""};
 const cle=suiviParams(o)+"|"+suiviVersion()+"|"+(db.emps||[]).length;suiviCharger(SANNU,cle,"api/v1/employes?"+suiviParams(o),j=>nomsRetenir(j.lignes||[]));
 const d=SANNU.data||{},list=d.lignes||[];const cGrade=(db.champs||[]).find(c=>c.code==="GRADE"),cStatut=(db.champs||[]).find(c=>c.code==="STATUT");
 const tete='<div class="fw-inbox-hd"><span class="fw-count">'+esc(t.sNbEmp.replace("{n}",d.total==null?"…":d.total))+"</span>"+'<label class="fw-check fw-sm"><input type="checkbox" data-sf="sortis"'+(s.sortis?" checked":"")+"><span>"+esc(t.sInclSortis)+"</span></label>"+'<div class="fw-spacer"></div>'+suiviFiltresHTML(true)+"</div>";
 if(SANNU.erreur&&SANNU.cle===cle)return tete+'<div class="fw-card"><div class="fw-empty"><strong>'+esc(t.svcErreur)+"</strong>"+esc(SANNU.erreur)+"</div></div>";
 if(!SANNU.data)return tete+'<div class="fw-hint" aria-busy="true" style="padding:24px">'+esc(t.chargement)+"</div>";
 const auj=todayKey();
 const ligne=e=>{const chef=e.chefMat?empVue(e.chefMat)||empNomCharger(e.chefMat):null;const dp=deptPath(e.deptId),dCourt=String(dp).split(" / ").slice(-1)[0];const sorti=e.sortie&&e.sortie<auj;
  return'<tr class="fw-srow" data-act="tiroir" data-tid="'+esc(e.id)+'"><td><div class="fw-empcell">'+empAvatar(e,30)+"<div><strong>"+esc(e.prenom+" "+e.nom)+'</strong><span class="fw-mono">'+esc(e.mat)+"</span></div></div></td>"
  +(cGrade?'<td class="fw-sm">'+esc(e.grade||e.poste||"—")+"</td>":"")+'<td class="fw-sm" title="'+esc(dp)+'">'+esc(dCourt||"—")+"</td>"+(cStatut?'<td class="fw-sm">'+esc(e.contrat||"—")+"</td>":"")
  +'<td class="fw-sm">'+esc(chef?chef.prenom+" "+chef.nom:e.chefMat||"—")+"</td>"+'<td><span class="fw-st '+(sorti?"absent":"present")+'">'+esc(sorti?t.out:t.inService)+"</span></td></tr>"};
 const reste=(d.total||0)-list.length;
 return tete+(SANNU.cle!==cle?'<div class="fw-hint" aria-busy="true">'+esc(t.chargement)+"</div>":"")+(list.length?'<div class="fw-card"><div class="fw-tbl-wrap"><table class="fw-tbl fw-stbl"><thead><tr><th>'+esc(t.emp)+"</th>"+(cGrade?"<th>"+esc(t.sPoste)+"</th>":"")+"<th>"+esc(t.dept)+"</th>"+(cStatut?"<th>"+esc(t.sContrat)+"</th>":"")+"<th>"+esc(t.sResponsable)+"</th><th>"+esc(t.statut)+"</th></tr></thead><tbody>"+list.map(ligne).join("")+"</tbody></table></div></div>"
  +(reste>0?'<button type="button" class="fw-btn fw-plus" data-act="s-plus" data-sk="limAnnu">'+esc(t.sPlus.replace("{n}",reste))+"</button>":""):'<div class="fw-card"><div class="fw-empty"><strong>'+esc(t.emptyT)+"</strong>"+esc(t.noMatch)+"</div></div>")}
/* 56.33.11 — « Exporter » du Suivi des équipes : exporte l'onglet affiché avec ses filtres (anomalies, pointages &
   présences, annuaire) ; en grand effectif, toutes les pages sont lues sur le serveur. Auparavant le fichier ne
   contenait que « Pas de données tabulaires pour cette vue ». */
async function suiviExporter(fmt){const s=sEtat(),auj=todayKey(),q=(ui.q||"").trim(),srv=suiviSrv();let tab;
 const nomDe=e=>[e&&e.nom||"",e&&e.prenom||""];
 if(s.tab==="ano"){const lib={oubli:t.tagOubli,retard:t.tagRetard,depart:t.tagDepart||t.chDeparts,absence:t.tagAbsence,hs:t.tagHs};
  const det=a=>a.type==="oubli"?(a.mvts||(a.mv||[]).map(m=>({ts:" "+m[1],sens:m[2]}))).map(m=>String(m.ts).slice(11,16)+" "+(m.sens||"")).join(" "):a.min!=null?fmtMin(a.min):"";
  let items;if(srv){const p=suiviPeriode();const o={du:p.du,au:p.au,type:s.type&&s.type!=="cal"?s.type:"",dept:s.dept,chef:s.chef,site:ui.siteFilter||"",q};
   const r=await exportServeurPages((off,lim)=>grandFetch("anomalies",Object.assign({},o,{offset:off,limit:lim})).then(j=>({total:j.total,items:j.items||[],recalcul:j.recalcul})),500);
   const dec=anoDec();items=r.lignes.filter(a=>!dec[a.id])}else{items=suiviAnomalies();if(s.type&&s.type!=="cal")items=items.filter(a=>a.type===s.type)}
  tab={title:"suivi_anomalies",headers:["MATRICULE","NOM","PRENOM","DATE","ANOMALIE","DETAIL"],rows:items.map(a=>[a.e?a.e.mat:a.mat].concat(nomDe(a.e)).concat([dateAff(a.k),lib[a.type]||a.type,det(a)]))}}
 else if(s.tab==="ptg"){let du=auj,au=auj;if(s.date==="hier"){du=au=dAjout(auj,-1)}else if(s.date==="sem"){du=lundiDe(auj)}
  const L={present:t.stPresent,retard:t.stRetard,absent:t.stAbsent,conge:t.stConge,incomplet:t.stIncomplet,repos:t.rest,attendu:t.stAttendu};let rows=[];
  if(srv){const o={du,au,statut:s.statut||"",dept:s.dept||"",chef:s.chef||"",site:ui.siteFilter||"",q:q.length>=2?q:""};
   const r=await exportServeurPages((off,lim)=>grandFetch("presences",Object.assign({},o,{offset:off,limit:lim})),500);
   rows=r.lignes.map(it=>{const mv=it.mv||[],ent=mv.find(m=>m[2]==="E"),der=mv.length>=2?mv[mv.length-1]:null;const j=(db.jours||[]).find(x=>x.id===it.jid);
    return[it.mat].concat(nomDe(it.e)).concat([dateAff(it.d),it.jid==="repos"?t.rest:it.jid==="ferie"?t.holiday:horaireJour(j)||"",ent?ent[1]:"",der&&der[2]==="S"?der[1]:"",it.hp==null?"":hh(it.hp),it.st==="conge"&&it.abs?it.abs:L[it.st]||it.st])})}
  else{const groupes={present:["present","retard","incomplet"],retard:["retard"],absent:["absent"],conge:["conge"],incomplet:["incomplet"]};
   let l=suiviJours(du,au).map(r=>Object.assign({st:statutJour(r)},r));if(q.length>=2)l=l.filter(r=>(r.e.nom+" "+r.e.prenom+" "+r.e.prenom+" "+r.e.nom+" "+r.e.mat).toLowerCase().indexOf(q.toLowerCase())>=0);
   l=s.statut&&groupes[s.statut]?l.filter(r=>groupes[s.statut].indexOf(r.st.c)>=0):l.filter(r=>r.st.c!=="repos");
   rows=l.map(r=>{const ent=r.list.find(m=>m.sens==="E"),der=r.list.length>=2?r.list[r.list.length-1]:null;return[r.e.mat].concat(nomDe(r.e)).concat([dateAff(r.k),r.inf.jid==="repos"?t.rest:r.inf.jid==="ferie"?t.holiday:horaireJour(r.inf.jour)||"",ent?String(ent.ts).slice(11,16):"",der&&der.sens==="S"?String(der.ts).slice(11,16):"",hh(r.d.HP),r.st.l])})}
  tab={title:"suivi_presences",headers:["MATRICULE","NOM","PRENOM","DATE","HORAIRE","ENTREE","SORTIE","TOTAL","STATUT"],rows}}
 else{let l;if(srv){const depts=s.dept?Array.from(deptDescendants(s.dept)).join(","):"";const o={statut:s.sortis?"":"actifs",site:ui.siteFilter||"",dept:depts,chef:s.chef||"",contrat:s.contrat||"",q:q.length>=2?q:""};
   const r=await exportServeurPages((off,lim)=>fetch("api/v1/employes?"+suiviParams(Object.assign({},o,{offset:off,limit:lim})),{credentials:"same-origin",cache:"no-store"}).then(x=>{if(!x.ok)throw new Error("HTTP "+x.status);return x.json()}).then(j=>({total:j.total,items:j.lignes||[]})),500);
   l=r.lignes}
  else{const depts=s.dept?deptDescendants(s.dept):null;l=(db.emps||[]).filter(e=>(s.sortis||!e.sortie)&&(!ui.siteFilter||e.siteId===ui.siteFilter)&&empDansPerimetre(e)&&(!depts||depts.has(e.deptId))&&(!s.chef||e.chefMat===s.chef)&&(!s.contrat||champActuel(e,"STATUT")===s.contrat));
   if(q.length>=2)l=l.filter(e=>(e.nom+" "+e.prenom+" "+e.prenom+" "+e.nom+" "+e.mat+" "+(e.cin||"")).toLowerCase().indexOf(q.toLowerCase())>=0);l=l.map(e=>Object.assign({},e,{grade:champActuel(e,"GRADE"),contrat:champActuel(e,"STATUT")}))}
  const chefNom=m=>{const c=m&&(empVue(m));return c?c.prenom+" "+c.nom:m||""};
  tab={title:"suivi_annuaire",headers:["MATRICULE","NOM","PRENOM","POSTE","DEPARTEMENT","CONTRAT","RESPONSABLE","STATUT"],rows:l.map(e=>[e.mat,e.nom,e.prenom,e.grade||e.poste||"",deptPath(e.deptId),e.contrat||"",chefNom(e.chefMat),e.sortie&&e.sortie<auj?t.out:t.inService])}}
 if(!tab.rows.length){flash(t.expNoData||t.emptyT,"warn");return}exportEcrire(tab,fmt)}
/* 56.33.11 : grand effectif — après une décision (ou son annulation) dans le suivi, les compteurs et listes sont relus
   sur le serveur une fois l'enregistrement transmis (le compteur « Tout » restait inchangé jusqu'au prochain rechargement) */
(function(){if(typeof suiviAppliquer!=="function")return;const relire=()=>{if(typeof GRAND==="undefined"||!GRAND)return;setTimeout(()=>{try{GRAND_ANO_CLE="";SPRES.cle="";GRAND_ACCUEIL.t=0;if(ui.view==="suivi")render()}catch(e){}},2500)};
 const a=suiviAppliquer;suiviAppliquer=function(){const r=a.apply(this,arguments);if(r)relire();return r};const b=suiviAnnuler;suiviAnnuler=function(){const r=b.apply(this,arguments);relire();return r}})();
/* 56.33.11 — Validation des journées : pagination des journées et du registre (100 par page ; seules les 100 premières
   journées et les 200 premières anomalies étaient visibles, sans indication), export de l'onglet affiché. */
function valjPager(total,off,lim,k){if(!total||total<=lim&&!off)return"";const a=off+1,b=Math.min(off+lim,total);
 return'<div class="fw-u-row" style="gap:8px;align-items:center;margin-top:8px"><button type="button" class="fw-btn sm" data-act="valj-page" data-k="'+k+'" data-o="'+Math.max(0,off-lim)+'"'+(off>0?"":" disabled")+'>‹</button><span class="fw-hint">'+esc(t.annuPlage.replace("{a}",a).replace("{b}",b).replace("{n}",total))+'</span><button type="button" class="fw-btn sm" data-act="valj-page" data-k="'+k+'" data-o="'+(off+lim)+'"'+(b<total?"":" disabled")+">›</button></div>"}
document.addEventListener("click",ev=>{const b=ev.target&&ev.target.closest?ev.target.closest('[data-act="valj-page"]'):null;if(!b||b.disabled)return;ev.preventDefault();ev.stopPropagation();const s=valjEtat();s[b.dataset.k]=Math.max(0,+b.dataset.o||0);s.sel={};s.cle="";s.data=null;render()},true);
/* recherche (nom, prénom, matricule) transmise au serveur ; libellés des codes d'anomalie du registre */
/* compteur du rapport de recalcul : libellé du paramétrage, code en infobulle */
function rcLib(k){const a=(db.arits||[]).find(x=>x.code===k);return a&&(a.nom||a.libelle)?(a.nom||a.libelle)+(a.unite?" ("+a.unite+")":""):k}
function valjQ(){const q=String(ui.view==="valj"&&ui.q||"").trim();return q.length>=2?"&q="+encodeURIComponent(q):""}
function valjCodeLib(c){const L={ABSENCE_UNJUSTIFIED:t.vcAbs,LATE_ARRIVAL:t.vcRet,EARLY_DEPARTURE:t.vcDep,OVERTIME_TO_VALIDATE:t.vcHs,ERR_SINGLE_BADGE:t.vcUnique,ERR_NO_IN:t.vcSansEntree,ERR_SEQUENCE:t.vcSeq};return L[c]||c}
async function valjExporter(fmt){const s=valjEtat(),E=ETAT_LIB();const lire=async(url,cle)=>{const out=[];for(let off=0;off<EXPORT_MAX;off+=500){const r=await fetch(url+"&limit=500&offset="+off,{credentials:"same-origin",cache:"no-store"});if(r.status===401){apiSessionPerdue();throw new Error("session")}const j=await r.json();if(!r.ok)throw new Error(j.message||"HTTP "+r.status);const l=j[cle]||[];out.push.apply(out,l);if(l.length<500)break}return out};let tab;
 if(s.tab==="anomalies"){const l=await lire("api/v1/registre-anomalies?du="+s.du+"&au="+s.au+(s.statut?"&statut="+s.statut:"")+(s.gravite?"&gravite="+s.gravite:"")+valjQ(),"items");
  tab={title:"registre_anomalies",headers:["DATE","MATRICULE","NOM","PRENOM","CODE","GRAVITE","STATUT","RESPONSABLE","ACTION"],rows:l.map(a=>[dateAff(a.d),a.mat,a.nom||"",a.prenom||"",valjCodeLib(a.code),t["valjG_"+a.gravite]||a.gravite,t["valjSt_"+a.statut]||a.statut,a.responsable||"",a.action||a.motif||""])}}
 else if(s.tab==="ajust"){const r=await fetch("api/v1/ajustements",{credentials:"same-origin",cache:"no-store"});const j=await r.json();
  tab={title:"ajustements",headers:["MATRICULE","JOURNEE ORIGINE","IMPUTE AU","COMPTEUR","ECART (H)","MOTIF","JUSTIFICATIF","STATUT","AUTEUR","VALIDE PAR"],rows:(j.items||[]).map(x=>[x.mat,dateAff(x.d_origine),dateAff(x.d_imputation),x.compteur,String(x.delta).replace(".",","),x.motif||"",x.justificatif||"",t["valjAjS_"+x.statut]||x.statut,x.auteur||"",x.valide_par||""])}}
 else if(s.tab==="valider"){const etat=s.voir||(s.niveau==="rh"?"APPROUVEE_MANAGER":"CORRIGEE");if(etat==="APPROUVEE_AUTO"){flash(t.expNoData||t.emptyT,"warn");return}
  const l=await lire("api/v1/journees?du="+s.du+"&au="+s.au+"&etat="+etat+valjQ(),"items");
  tab={title:"journees_"+etat.toLowerCase(),headers:["DATE","MATRICULE","NOM","PRENOM","ETAT","ANOMALIES OUVERTES","DERNIER CHANGEMENT","PAR"],rows:l.map(r=>[dateAff(r.d),r.mat,r.nom||"",r.prenom||"",E[r.etat]||r.etat,r.ouvertes||0,String(r.maj||"").slice(0,16).replace("T"," "),r.auteur||""])}}
 else{flash(t.expNoData||t.emptyT,"warn");return}
 if(!tab.rows.length){flash(t.expNoData||t.emptyT,"warn");return}exportEcrire(tab,fmt)}
/* 56.33.11 — Demandes. En grand effectif, les fiches des salariés concernés n'étaient pas chargées : durée « 0 j »,
   circuit et valideur introuvables (personne ne pouvait valider), choix du salarié limité aux salariés chargés.
   Les fiches complètes des demandeurs et de leurs responsables sont lues sur le serveur. */
const DMD_FICHES=new Set;let DMD_FICHES_EN_COURS=false;
function dmdFichesCompleter(){if(!annuSrv()||DMD_FICHES_EN_COURS)return;orgRespsCompleter();const connus=new Set((db.emps||[]).filter(e=>!e._leger).map(e=>String(e.mat)));
 const l=Array.from(new Set((db.dmd||[]).map(d=>String(d.mat)))).filter(m=>m&&!connus.has(m)&&!DMD_FICHES.has(m));
 if(!l.length){/* responsables des demandeurs (premier niveau des circuits) */const chefs=Array.from(new Set((db.emps||[]).filter(e=>!e._leger&&(db.dmd||[]).some(d=>String(d.mat)===String(e.mat))&&e.chefMat).map(e=>String(e.chefMat)))).filter(m=>!connus.has(m)&&!DMD_FICHES.has(m));if(!chefs.length)return;l.push.apply(l,chefs)}
 const lot=l.slice(0,1000);lot.forEach(m=>DMD_FICHES.add(m));DMD_FICHES_EN_COURS=true;Promise.resolve(empsCompleter(lot)).then(()=>{DMD_FICHES_EN_COURS=false;NBJ_CACHE=null;if(ui.view==="dmd"||ui.view==="bord")render();if(l.length>lot.length)setTimeout(dmdFichesCompleter,0)}).catch(()=>{DMD_FICHES_EN_COURS=false})}
/* mode Journée ou Heures : la date de fin suit la date choisie (sinon « La date de fin précède la date de début ») */
document.addEventListener("input",dmdDateSuit,true);document.addEventListener("change",dmdDateSuit,true);
function dmdDateSuit(ev){const el=ev.target;if(!el||!el.dataset||el.dataset.bind!=="du"||!el.closest||!el.closest(".fw-dmdpanel"))return;const dm=ui.sel;if(!dm||!el.value)return;const fin=document.querySelector('.fw-dmdpanel [data-bind="au"]');if(!fin||!dm.au||dm.au===dm.du){dm.au=el.value;return}if(dm.au<=el.value){dm.au=dAjout(el.value,1);fin.value=dm.au;const tx=fin.parentElement&&fin.parentElement.querySelector(".fw-jj-txt");if(tx)tx.value=dateAff(dm.au)}}
/* salarié choisi dans une nouvelle demande (grand effectif) : fiche complète lue sur le serveur (calendrier, circuit) */
document.addEventListener("change",ev=>{const el=ev.target;if(!el||!el.dataset||el.dataset.bind!=="mat"||!el.closest||!el.closest(".fw-dmdpanel")||!annuSrv())return;const m=String(el.value||"").trim();if(!m||(db.emps||[]).some(e=>e.mat===m&&!e._leger))return;empCharger(m).then(e=>{if(!e)flash(t.dmdEmpInconnu,"warn");render()}).catch(()=>{})});
Object.assign(T.fr,{dmdEmpInconnu:"Salarié inconnu ou hors de votre périmètre : choisissez-le dans la liste.",dmdEmpCharge:"Chargement de la fiche du salarié…"});
Object.assign(T.en,{dmdEmpInconnu:"Unknown employee or outside your scope: pick one from the list.",dmdEmpCharge:"Loading the employee record…"});
