/* 56.33.11 — demande portant sur une période clôturée : elle ne peut plus être acceptée ni refusée (le serveur refuse
   l'écriture). L'écran annonçait « Demande acceptée » et la notification partait vers le salarié alors que la demande
   restait en attente sur le serveur. Toutes les actions de décision sont arrêtées avec une explication. */
function dmdCloturee(d){try{return!!d&&!d.rectifDe&&jourCloture(d.du||d.d||"")}catch(e){return false}}
document.addEventListener("click",ev=>{const b=ev.target&&ev.target.closest?ev.target.closest('[data-act="dmd-val"],[data-act="dmd-ref"],[data-act="dmdok"],[data-act="dmdko"],[data-act="ntf-dmdok"],[data-act="ntf-dmdko"]'):null;if(!b)return;
 const id=b.dataset.id||(ui.sel&&ui.sel.id);const d=(db.dmd||[]).find(x=>x.id===id);if(!dmdCloturee(d))return;ev.preventDefault();ev.stopImmediatePropagation();flash(t.dmdClotureeH,"warn")},true);
