/* 56.33.11 — « Mon équipe » sur téléphone : la barre d'onglets du bas (Aujourd'hui, Demandes, Suivi, Moi) restait
   seulement sur l'écran Aujourd'hui ; ouvrir « Demandes » la faisait disparaître, sans retour possible autrement que par
   le menu. Elle est ajoutée aux écrans qu'elle ouvre (affichée seulement sur petit écran, comme sur Aujourd'hui). */
function mgrNavHtml(){const o=[["mgr",t.mgOngletJour],["dmd",t.mgOngletDmd],["suivi",t.mgOngletSuivi],["portal",t.mgOngletMoi]].filter(x=>VIEWS[x[0]]&&ecranAutorise(x[0]));
 return'<div class="fw-mg-espace"></div><nav class="fw-mg-onglets" aria-label="'+esc(t.mgNav)+'">'+o.map(x=>'<button type="button" data-view="'+x[0]+'"'+(ui.view===x[0]?' class="on" aria-current="page"':"")+">"+esc(x[1])+"</button>").join("")+"</nav>"}
["dmd","suivi","portal"].forEach(v=>{const f=VIEWS[v];if(typeof f!=="function")return;VIEWS[v]=function(){const h=f.apply(this,arguments);try{return ecranAutorise("mgr")?h+mgrNavHtml():h}catch(e){return h}}});
if(typeof document!=="undefined"&&document.head&&!document.getElementById("fwMgNavCss")){const st=document.createElement("style");st.id="fwMgNavCss";st.textContent=".fw-mg-espace{display:none}@media (max-width:600px){.fw-mg-espace{display:block;height:64px}}";document.head.appendChild(st)}
