function ptgSrvSync(){const P=ui.ptgP||{},b=ptgBornesK();const s=ui.ptgSrv||(ui.ptgSrv={off:0,d:null,enCours:false,cle:""});const base=[b.du,b.au,(ui.q||"").trim(),P.dept||"",P.chef||"",ui.siteFilter||""].join("|");if(s.base!==base){s.base=base;s.off=0}s.du=b.du;s.au=b.au;s.q=(ui.q||"").trim();s.dept=P.dept||"";s.chef=P.chef||"";s.site=ui.siteFilter||"";return s}
