function ptgCompteHero(rows){const tab=ui.ptgTab;if(ANNUAIRE_PAGINE&&tab==="journal"){const d=(ui.ptgSrv||{}).d;return d?d.total:"…"}const g=ui.grandInfo;if(GRAND&&g&&g.vue===tab&&g.total!=null)return g.total;return rows.length}
function grandSemLigne(r){return{id:r.mat+"|"+r.du,_mat:r.mat,_nom:r.e?r.e.nom+" "+r.e.prenom:r.mat,_dept:deptPath(r.e&&r.e.deptId),_sem:lundiDe(r.du),_jours:r.jours||0,_ht:r.prevu,_hp:r.fait,_ec:r.ecart,_dep:(Number(r.hsMin)||0)/60,_ano:Number(r.inc)||0}}
function grandLignesSemaines(){const o=Object.assign(grandFiltresPtg(),{gran:"semaine",offset:ui.grandOff&&ui.grandOff.semaines||0,limit:50});const j=grandPage("semaines","synthese",o);ui.grandInfo={vue:"semaines",total:j.total,offset:o.offset,limit:o.limit,chargement:!!j.chargement,unite:t.uniteSalaries};return(j.items||[]).map(grandSemLigne)}
const COLS_SEM_GRAND=()=>[{k:"sem",l:t.semaineDu,cls:"fw-mono",get:r=>r._sem},{k:"nom",l:t.emp,cls:"fw-ptgnom",get:r=>r._mat+" "+r._nom,html:r=>'<span class="fw-mono fw-muted">'+esc(r._mat)+"</span> "+esc(r._nom)},{k:"dept",l:t.dept,cls:"fw-sm",get:r=>r._dept},{k:"j",l:t.jrs,cls:"fw-num",get:r=>String(r._jours)},{k:"ht",l:t.htCourt,cls:"fw-num",get:r=>hh(r._ht)},{k:"hp",l:t.hpCourt,cls:"fw-num",get:r=>hh(r._hp)},{k:"ec",l:t.ecart,cls:"fw-num",get:r=>hh(r._ec),html:r=>'<span style="color:'+(r._ec>.01?"#0f766e":r._ec<-.01?"var(--danger)":"inherit")+'">'+esc(hh(r._ec))+"</span>"},{k:"dep",l:t.semDep,cls:"fw-num",get:r=>r._dep?hh(r._dep):"—"},{k:"ano",l:t.semInc,cls:"fw-num",get:r=>r._ano?String(r._ano):"—"}];
