const COLS_REGUL_GRAND=()=>[{k:"d",l:t.colDate,cls:"fw-mono",get:r=>r._date},{k:"nom",l:t.emp,cls:"fw-ptgnom",get:r=>r._mat+" "+r._nom,html:r=>'<span class="fw-mono fw-muted">'+esc(r._mat)+"</span> "+esc(r._nom)},{k:"dept",l:t.dept,cls:"fw-sm",get:r=>r._dept},{k:"mv",l:t.regBadges,cls:"fw-mono fw-sm",get:r=>r._mvts},{k:"act",l:"",get:()=>"",html:r=>'<button type="button" class="fw-btn sm pri" data-act="pj-ouvrir" data-mat="'+esc(r._mat)+'" data-d="'+esc(r._date)+'">'+esc(t.regCorriger)+"</button>"}];

/* Calendrier (recette) : une période clôturée ne doit jamais changer. La trame hebdomadaire n'avait pas de date d'effet
   (la modifier réécrivait tout l'historique, périodes clôturées comprises), et le pinceau, « Effacer les exceptions » et
   l'affectation en masse acceptaient des jours clôturés. Trame datée : cal.hebdoHist = [{jusqu, hebdo}] (trames
   antérieures, par date croissante) ; cal.hebdo reste la trame en vigueur ensuite. Même moteur dans le navigateur et
   sur le serveur. */
function hebdoAt(cal,k){const h=cal&&cal.hebdoHist;if(Array.isArray(h))for(let i=0;i<h.length;i++){const x=h[i];if(x&&k<=x.jusqu&&x.hebdo)return x.hebdo}return cal&&cal.hebdo||{}}
function calEffetMin(cal){const c=derniereCloture()||"";const h=(cal.hebdoHist||[]).reduce((m,x)=>x&&x.jusqu>m?x.jusqu:m,"");const b=c>h?c:h;return b?dAjout(b,1):""}
function calTrameEffetHTML(cal){const min=calEffetMin(cal);if(!ui.calEffet)ui.calEffet={};let v=ui.calEffet[cal.id];if(!v||min&&v<min)v=ui.calEffet[cal.id]=min;const jn=id=>id==="repos"?t.rest:((db.jours||[]).find(j=>j.id===id)||{}).nom||id;
 const ant=(cal.hebdoHist||[]).filter(x=>x&&x.hebdo).map(x=>'<div class="fw-hint">'+esc(t.calJusqu.replace("{d}",dateAff(x.jusqu)))+" : "+esc(t.days.map((d,i)=>d+" "+jn(x.hebdo[i]||"repos")).join(" · "))+"</div>").join("");
 return(min?field(t.calEffetL,'<input type="date" data-caleffet="'+esc(cal.id)+'" min="'+esc(min)+'" value="'+esc(v)+'">',t.calEffetH):'<div class="fw-hint">'+esc(t.calEffetSansClot)+"</div>")+(ant?'<div class="fw-sec">'+esc(t.calTramesAnt)+"</div>"+ant:"")}
document.addEventListener("change",ev=>{const el=ev.target;if(!el||!el.dataset)return;
 if(el.dataset.caleffet!==undefined){const cal=db.cals.find(c=>c.id===el.dataset.caleffet);if(!cal)return;const min=calEffetMin(cal);if(min&&el.value&&el.value<min){flash(t.calEffetMin.replace("{d}",dateAff(min)),"err");el.value=min}if(!ui.calEffet)ui.calEffet={};ui.calEffet[cal.id]=el.value||min;return}
 if(el.dataset.hebdo===undefined)return;calTrameFiger(ev)},true);
/* la trame est enregistrée par le gestionnaire « input » de l'écran : la trame en vigueur est figée juste avant */
document.addEventListener("input",ev=>{const el=ev.target;if(el&&el.dataset&&el.dataset.hebdo!==undefined)calTrameFiger(ev)},true);
function calTrameFiger(ev){if(ev.__calFige)return;ev.__calFige=true;const cal=db.cals.find(c=>c.id===ui.calId);if(!cal)return;const min=calEffetMin(cal);if(!min)return;
 const eff=(ui.calEffet||{})[cal.id]||min;if(eff<min){ev.stopPropagation();flash(t.calEffetMin.replace("{d}",dateAff(min)),"err");render();return}
 const veille=dAjout(eff,-1);if(!Array.isArray(cal.hebdoHist))cal.hebdoHist=[];if(!cal.hebdoHist.some(x=>x&&x.jusqu===veille)){cal.hebdoHist.push({jusqu:veille,hebdo:clone(cal.hebdo||{})});cal.hebdoHist.sort((a,b)=>a.jusqu<b.jusqu?-1:1)}}
document.addEventListener("click",ev=>{if(ui.view!=="cal")return;const el=ev.target&&ev.target.closest?ev.target.closest("[data-brush],[data-act]"):null;if(!el)return;const der=derniereCloture();
 if(el.dataset.brush){if(!ui.days.length||!der)return;const fermes=ui.days.filter(k=>jourCloture(k));if(!fermes.length)return;ui.days=ui.days.filter(k=>!jourCloture(k));if(!ui.days.length){ev.stopPropagation();flash(t.calClosTout.replace("{d}",dateAff(der)),"err");render();return}flash(t.calClosPartiel.replace("{n}",fermes.length).replace("{d}",dateAff(der)),"warn");return}
 const act=el.dataset.act;if(act!=="clearexc"&&act!=="clearalt")return;ev.stopPropagation();const cal=normCal(db.cals.find(c=>c.id===ui.calId));if(!cal)return;
 const cles=(ui.days.length?ui.days:Object.keys(cal.exc)).filter(k=>cal.exc[k]&&!jourCloture(k)&&(act==="clearexc"||(cal.exc[k].alt||[]).length));const fermes=(ui.days.length?ui.days:[]).filter(k=>jourCloture(k)).length;
 if(!cles.length){flash(t.calRienEffacer,"warn");return render()}cles.forEach(k=>{if(act==="clearexc")delete cal.exc[k];else cal.exc[k].alt=[]});save();flash(t.calExcEffacees.replace("{n}",cles.length)+(fermes?" "+t.calClosPartiel.replace("{n}",fermes).replace("{d}",dateAff(der)):""),"ok");render()},true);
/* suppression d'un calendrier encore présent dans l'historique d'affectation : refusée (journées passées sans calendrier) */
(function(){const avant=delDemander;delDemander=function(ent,id){if(ent!=="cals")return avant(ent,id);const local=()=>(db.emps||[]).filter(e=>calHistOf(e).some(h=>h.calId===id)||e.calId===id).length;
 const fin=n=>{if(n>0){flash(t.calSupprUtilise.replace("{n}",n),"err");render();return}avant(ent,id);render()};
 if(typeof ANNUAIRE_PAGINE!=="undefined"&&ANNUAIRE_PAGINE&&!DEMO){fetch("api/v1/employes/compter?critere=cal&id="+encodeURIComponent(id),{credentials:"same-origin",cache:"no-store"}).then(r=>r.ok?r.json():{n:local()}).then(j=>fin(Math.max(Number(j.n)||0,local()))).catch(()=>fin(local()));return}fin(local())}})();

/* Journée type (recette). 1) Cache des calculs : relu après chaque enregistrement (signature sur le contenu).
   2) Définition datée : jour.hist = [{jusqu, def:{theo, plages, tolIn, tolOut, nuit}}] par date croissante ; modifier une
   journée type ne réécrit plus les périodes clôturées (même moteur dans le navigateur et sur le serveur). */
var JV_REFSEQ=0,JV_REFVU=-1;
function jvHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36)+":"+s.length}
(function(){const avant=save;save=function(){JV_REFSEQ++;return avant.apply(this,arguments)}})();
const JOUR_CALC=["theo","plages","tolIn","tolOut","nuit"];
function jourDef(j){const o={};JOUR_CALC.forEach(k=>{o[k]=j[k]===undefined?null:clone(j[k])});return o}
function jourAt(j,k){const h=j&&j.hist;if(Array.isArray(h))for(let i=0;i<h.length;i++){const x=h[i];if(x&&x.def&&k<=x.jusqu)return Object.assign({},j,x.def)}return j}
function jourFigerAvant(row){const clot=derniereCloture();if(!clot||!row)return;const old=(db.jours||[]).find(x=>x.id===row.id);if(!old)return;
 if(JSON.stringify(jourDef(old))===JSON.stringify(jourDef(row)))return;const h=Array.isArray(row.hist)?row.hist.slice():[];if(h.some(x=>x&&x.jusqu>=clot))return;h.push({jusqu:clot,def:jourDef(old)});h.sort((a,b)=>a.jusqu<b.jusqu?-1:1);row.hist=h}
function jourDureePlages(pl){return(pl||[]).filter(p=>p&&p.t!=="pause"&&p.a&&p.b).reduce((s,p)=>{let d=toMin(p.b)-toMin(p.a);if(d<=0)d+=1440;return s+d},0)}
function jourErreurs(row,e){const n=x=>Number(x);if(!e.nom&&(db.jours||[]).some(x=>x.id!==row.id&&String(x.nom||"").trim().toLowerCase()===String(row.nom||"").trim().toLowerCase()))e.nom=t.jouNomDouble;
 ["tolIn","tolOut"].forEach(k=>{const v=row[k];if(v!==undefined&&v!==""&&v!==null&&(isNaN(n(v))||n(v)<0||n(v)>240))e[k]=t.jouTol});
 if(!e.plages)(row.plages||[]).forEach(p=>{if(e.plages||!p||p.t!=="pause"||!p.a||!p.b)return;let lg=toMin(p.b)-toMin(p.a);if(lg<=0)lg+=1440;const d=n(p.duree);if(isNaN(d)||d<1||d>lg||n(p.maxDep||0)<0||n(p.penal||0)<0)e.plages=t.jouPause.replace("{a}",p.a).replace("{b}",p.b).replace("{n}",lg)});
 if(!e.theo&&!e.plages){const pl=jourDureePlages(row.plages);if(pl>0&&n(row.theo)>pl)e.theo=t.jouTheoPlages.replace("{th}",hrs(n(row.theo))).replace("{pl}",hrs(pl))}}
function jourVersionsHTML(j){const clot=derniereCloture();const h=(j.hist||[]).filter(x=>x&&x.def);return(clot?'<div class="fw-hint">'+esc(t.jouVersH.replace("{d}",dateAff(clot)))+"</div>":"")+(h.length?'<div class="fw-sec">'+esc(t.jouVersAnt)+"</div>"+h.map(x=>'<div class="fw-hint">'+esc(t.calJusqu.replace("{d}",dateAff(x.jusqu)))+" : "+esc(hrs(x.def.theo))+" · "+esc((x.def.plages||[]).map(p=>p.a+"–"+p.b).join(", "))+"</div>").join(""):"")}
(function(){const avant=put;put=function(key,row){if(key==="jours")jourFigerAvant(row);return avant(key,row)}})();
function calsUtilisantJour(id){return(db.cals||[]).filter(c=>{const v=o=>Object.values(o||{}).indexOf(id)>=0;if(v(c.hebdo)||(c.hebdoHist||[]).some(x=>x&&v(x.hebdo)))return true;return Object.values(c.exc||{}).some(x=>x&&(x===id||x.j===id||(x.alt||[]).indexOf(id)>=0))})}
(function(){const avant=delDemander;delDemander=function(ent,id){if(ent==="jours"){const l=calsUtilisantJour(id);if(l.length){flash(t.jouSupprUtilise.replace("{n}",l.length).replace("{l}",l.map(c=>c.nom).join(", ")),"err");return}}return avant(ent,id)}})();

/* Types de temps (recette) : le code relie les formules (TT_xxx), les absences et les demandes ; la classe, le mode de
   saisie et « rémunéré » changent le calcul de toutes les journées où le type est utilisé. Contrôlés ici et par le
   serveur (sur toute la base). */
const TT_SYSTEME=["030","031","034","035","040"];
function ttSysteme(x){return!!x&&TT_SYSTEME.indexOf(String(x.code))>=0}
function ttUsage(id){const clot=derniereCloture()||"";let n=0,clos=0;(db.abs||[]).concat(db.dmd||[]).forEach(x=>{if(x&&x.tt===id){n++;if(clot&&String(x.du||x.d||"")<=clot)clos++}});return{n,clos}}
function ttErreurs(row,e){const orig=(db.tt||[]).find(x=>x.id===row.id);if(!e.nom&&(db.tt||[]).some(x=>x.id!==row.id&&String(x.nom||"").trim().toLowerCase()===String(row.nom||"").trim().toLowerCase()))e.nom=t.ttNomDouble;if(!orig)return;
 if(!e.code&&String(orig.code)!==String(row.code))e.code=t.ttCodeFige.replace("{c}",orig.code);const u=ttUsage(row.id);
 if((orig.saisie||"jour")!==(row.saisie||"jour")&&u.n)e.saisie=t.ttSaisieUtilise.replace("{n}",u.n);
 if(u.clos){const clot=dateAff(derniereCloture());if(Number(orig.cls)!==Number(row.cls))e.cls=t.ttClosUtilise.replace("{k}",t.cls).replace("{n}",u.clos).replace("{d}",clot);else if(!!orig.paye!==!!row.paye)e.paye=t.ttClosUtilise.replace("{k}",t.paid).replace("{n}",u.clos).replace("{d}",clot)}}
(function(){const avant=delDemander;delDemander=function(ent,id){if(ent==="tt"){const x=(db.tt||[]).find(y=>y.id===id);if(ttSysteme(x)){flash(t.ttSupprSysteme.replace("{c}",x.code),"err");return}const u=ttUsage(id);if(u.n){flash(t.ttSupprUtilise.replace("{n}",u.n),"err");return}}return avant(ent,id)}})();

/* Arithmétique (recette) : une dépendance circulaire arrêtait TOUS les compteurs (heures, solde de congés… à 0) ; un code
   renommé ou supprimé cassait les formules qui l'utilisent ; une formule modifiée réécrivait les périodes clôturées.
   Formule datée : a.hist = [{jusqu, f}] (par date croissante), même moteur dans le navigateur et sur le serveur. */
function arAt(a,k){const h=a&&a.hist;if(Array.isArray(h))for(let i=0;i<h.length;i++){const x=h[i];if(x&&x.f&&k<=x.jusqu)return Object.assign({},a,{f:x.f})}return a}
function arRefs(f){let r=null;try{r=parseFormula(f)}catch(e){}if(!r||!r.ok)return[];const x=refsOf(r.ast);return x.vars.concat(x.cums)}
function arDependants(code,id){const out=[];(db.arits||[]).forEach(a=>{if(a.id!==id&&arRefs(a.f).indexOf(code)>=0)out.push({lib:a.code})});(db.etats||[]).forEach(e=>{if((e.champs||[]).indexOf(id)>=0)out.push({lib:t.arEtat+" « "+e.nom+" »"})});return out}
function arCycleAvec(row){const liste=(db.arits||[]).filter(a=>a.id!==row.id).concat([row]);const par={};liste.forEach(a=>{par[a.code]=a});const etat={},pile=[];let trouve=null;
 const visite=a=>{if(trouve)return;if(etat[a.code]==="fait")return;if(etat[a.code]==="cours"){const i=pile.indexOf(a.code);trouve=pile.slice(i).concat([a.code]);return}etat[a.code]="cours";pile.push(a.code);arRefs(a.f).forEach(c=>{if(par[c]&&par[c]!==a)visite(par[c])});pile.pop();etat[a.code]="fait"};liste.forEach(visite);return trouve}
function arErreurs(row,e){const orig=(db.arits||[]).find(x=>x.id===row.id);if(orig&&!e.code&&String(orig.code)!==String(row.code))e.code=t.arCodeFige;
 if(!e.f&&!e.code){const c=arCycleAvec(row);if(c)e.f=t.arCycle.replace("{c}",c.join(" → "))}
 const clot=derniereCloture();if(orig&&clot){[["unite",t.unit],["period",t.period],["agg",t.aggL]].forEach(p=>{if(!e[p[0]]&&String(orig[p[0]]||"")!==String(row[p[0]]||""))e[p[0]]=t.arClos.replace("{k}",p[1]).replace("{d}",dateAff(clot))})}}
function arFigerAvant(row){const clot=derniereCloture();if(!clot||!row)return;const old=(db.arits||[]).find(x=>x.id===row.id);if(!old||String(old.f)===String(row.f))return;const h=Array.isArray(row.hist)?row.hist.slice():[];if(h.some(x=>x&&x.jusqu>=clot))return;h.push({jusqu:clot,f:old.f});h.sort((a,b)=>a.jusqu<b.jusqu?-1:1);row.hist=h}
function arVersionsHTML(a){const clot=derniereCloture();const h=(a.hist||[]).filter(x=>x&&x.f);return(clot&&(db.arits||[]).some(x=>x.id===a.id)?'<div class="fw-hint">'+esc(t.arVersH.replace("{d}",dateAff(clot)))+"</div>":"")+(h.length?'<div class="fw-sec">'+esc(t.arVersAnt)+"</div>"+h.map(x=>'<div class="fw-hint fw-mono">'+esc(t.calJusqu.replace("{d}",dateAff(x.jusqu)))+" : "+esc(x.f)+"</div>").join(""):"")}
(function(){const avant=put;put=function(key,row){if(key==="arits")arFigerAvant(row);return avant(key,row)}})();
(function(){const avant=delDemander;delDemander=function(ent,id){if(ent==="arits"){const a=(db.arits||[]).find(x=>x.id===id);const d=a?arDependants(a.code,a.id):[];if(d.length){flash(t.arSupprDep.replace("{l}",d.map(x=>x.lib).join(", ")),"err");return}}return avant(ent,id)}})();

/* Badgeages répétés (règle DOUBLON_MIN) : les contrôles « journée incomplète » portent sur les badgeages retenus par la
   règle (ils lisaient la liste brute et signalaient des journées que la règle avait rendues complètes) */
var DBL_EMPS=null,DBL_EMPS_REF=null;
function dblEmp(mat){const l=db&&db.emps||[];if(DBL_EMPS_REF!==l||!DBL_EMPS){DBL_EMPS=new Map(l.map(e=>[String(e.mat),e]));DBL_EMPS_REF=l}return DBL_EMPS.get(String(mat))||null}
function dblListe(mat,dk){const e=dblEmp(mat);try{return e?mvtsCalc(e,dk):mvtsDe(mat,dk)}catch(x){return mvtsDe(mat,dk)}}
function jourIncoherent(mat,dk){/* correctif 49 : badgeages RATTACHÉS à la journée (poste de nuit : sortie du lendemain), comme le calcul — avant : badgeages de la date seule, toute nuit 22:00 → 06:00 était « incomplète » */const e=dblEmp(mat);if(e){try{const jv=jourVars(e,dk),p=dk.split("-").map(Number);return seqIncoherente(mvtsJour(e,p[0],p[1]-1,p[2],jv.inf.jour).map(x=>x.mv))}catch(x){}}return seqIncoherente(dblListe(mat,dk))}
function jourIncoherentCle(k){const i=String(k).lastIndexOf("|");return jourIncoherent(k.slice(0,i),k.slice(i+1))}
function dblRetenus(mat,dk){return new Set(dblListe(mat,dk).map(m=>String(m.id)))}
function dblEcartes(emp,dk){try{return Math.max(0,mvtsDe(emp.mat,dk).length-mvtsCalc(emp,dk).length)}catch(x){return 0}}
function dblSuffixe(n){return n>0?" ("+t.dblEcartes.replace("{n}",n)+")":""}

/* filtres de colonne : tous les mots saisis, dans n'importe quel ordre (« asma baccouche » trouve « Baccouche Asma ») */
function motsDans(txt,v){const m=String(v).split(/\s+/).filter(Boolean);return!m.length||m.every(x=>txt.indexOf(x)>=0)}

/* ===== correctif 5 : Contrôle d'accès ===== */
/* Accès en masse en grand effectif : sélection et application sur tout le personnel par le serveur (api/v1/employes/acces-masse) */
function accSrvCorps(){const m=ui.acc||{};return{sites:m.sites||[],depts:m.depts||[],filtres:m.filtres||{},zoneSrc:m.zoneSrc||"",zoneDst:m.zoneDst||"",planDst:m.planDst||"",from:m.from||todayKey(),sortis:!!m.sortis}}
function accSrvCharger(force){const corps=accSrvCorps(),cle=JSON.stringify(corps);if(!force&&ui.accSrv&&(ui.accSrv.cle===cle||ui.accSrv.attente===cle))return;ui.accSrv=Object.assign({},ui.accSrv||{},{attente:cle});fetch("api/v1/employes/acces-masse",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:cle}).then(r=>{if(r.status===401){apiSessionPerdue();throw new Error("session")}return r.json().then(j=>{if(!r.ok)throw new Error(j.message||j.erreur||"HTTP "+r.status);return j})}).then(j=>{if(!ui.accSrv||ui.accSrv.attente!==cle)return;ui.accSrv={cle,total:j.total,aModifier:j.aModifier,apercu:j.apercu||[]};render()}).catch(e=>{if(ui.accSrv&&ui.accSrv.attente===cle){ui.accSrv={cle,total:0,aModifier:0,apercu:[]};flash(e.message,"warn");render()}})}
function accSrvAppliquer(){const n=(ui.accSrv||{}).aModifier||0;if(!n)return;const m=ui.acc||{},d=m.from||todayKey();if(d<todayKey()){flash(t.accDatePassee,"err");return}fwConfirm({message:accConfirmTexte(n,m,d,(ui.accSrv||{}).programmes||0),danger:m.planDst==="aucun",okLabel:t.appliquer},function(ok){if(!ok)return;const corps=Object.assign(accSrvCorps(),{appliquer:true});fetch("api/v1/employes/acces-masse",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(corps)}).then(r=>r.json().then(j=>({r,j}))).then(({r,j})=>{if(!r.ok){flash(j.message||j.erreur||t.svcErreur,"err");return}flash(t.affectDone.replace("{n}",j.modifies||0)+((j.ignores||[]).length?" — "+j.ignores.join(", "):""),(j.ignores||[]).length?"warn":"ok");ui.accSrv=null;try{if(typeof annuInvalider==="function")annuInvalider()}catch(e){}render()}).catch(e=>flash(e.message,"err"))})}
/* Suppression d'une zone, d'un plan ou d'une plage encore utilisés : refusée (avant : références orphelines ; un plan supprimé laissait le salarié autorisé) */
(function(){const avant=delDemander;delDemander=function(ent,id){if(ent!=="zones"&&ent!=="aplans"&&ent!=="aplages")return avant(ent,id);
const fin=(n,msg)=>{if(n>0){flash(msg.replace("{n}",n),"err");render();return}avant(ent,id);render()};
if(ent==="aplages"){const n=(db.aplans||[]).filter(p=>[0,1,2,3,4,5,6].some(i=>(p.hebdo||{})[i]===id)||p.ferie===id).length;return fin(n,t.accSupprPlage)}
if(ent==="zones"){const z=(db.zones||[]).find(x=>x.id===id)||{},portes=(z.portes||[]).map(p=>p.id),nl=(db.terms||[]).filter(r=>r.porteId&&portes.indexOf(r.porteId)>=0).length;if(nl)return fin(nl,t.accSupprZoneLect)}
const crit=ent==="zones"?"zone":"plan",local=()=>(db.emps||[]).filter(e=>(e.acces||[]).some(a=>ent==="zones"?a.zoneId===id:a.planId===id||(a.hist||[]).some(h=>h.planId===id))).length,msg=ent==="zones"?t.accSupprZone:t.accSupprPlan;
if(typeof ANNUAIRE_PAGINE!=="undefined"&&ANNUAIRE_PAGINE&&!DEMO){fetch("api/v1/employes/compter?critere="+crit+"&id="+encodeURIComponent(id),{credentials:"same-origin",cache:"no-store"}).then(r=>r.ok?r.json():{n:local()}).then(j=>fin(Math.max(Number(j.n)||0,local()),msg)).catch(()=>fin(local(),msg));return}
fin(local(),msg)}})();
/* Lecteurs rattachés à une porte retirée d'une zone : détachés à l'enregistrement de la zone */
(function(){const avant=put;put=function(key,row){const r=avant(key,row);if(r&&key==="zones"){const ids=new Set;(db.zones||[]).forEach(z=>(z.portes||[]).forEach(p=>ids.add(p.id)));let n=0;(db.terms||[]).forEach(x=>{if(x.porteId&&!ids.has(x.porteId)){x.porteId="";n++}});if(n)save()}return r}})();
/* Contrôles de saisie du contrôle d'accès */
(function(){const avant=champErreurs;const nomDouble=(l,row)=>(l||[]).some(x=>x.id!==row.id&&String(x.nom||"").trim().toLowerCase()===String(row.nom||"").trim().toLowerCase());
const vd=v=>v===undefined||v===null||String(v).trim()==="";champErreurs=function(ent,row){const e=avant(ent,row)||{};try{
if(ent==="aplages"&&!e.iv){const iv=(row.iv||[]).map(x=>{let a=toMin(x.a),b=toMin(x.b);if(b===0)b=1440;return b<=a?[[a,1440],[0,b]]:[[a,b]]});if((row.iv||[]).some(x=>x.a===x.b&&x.a!=="00:00")||(row.iv||[]).filter(x=>dureeIv([x])>=1440).length&&(row.iv||[]).length>1)e.iv=t.accIvVide;else{const seg=[].concat(...iv).sort((x,y)=>x[0]-y[0]);for(let i=1;i<seg.length;i++)if(seg[i][0]<seg[i-1][1]){e.iv=t.accIvChevauche;break}}}
if((ent==="aplages"||ent==="aplans"||ent==="zones")&&!e.nom&&!vd(row.nom)&&nomDouble(ent==="zones"?(db.zones||[]).filter(z=>z.siteId===row.siteId):db[ent],row))e.nom=t.accNomDouble;
if(ent==="zones"){if(vd(row.siteId))e.siteId=t.vRequis;const p=row.portes||[];if(p.some(x=>vd(x.nom)))e.portes=t.accPorteNom;else if(p.some((x,i)=>p.findIndex(y=>String(y.nom).trim().toLowerCase()===String(x.nom).trim().toLowerCase())!==i))e.portes=t.accPorteDouble}
if(ent==="emps"){const l=row.acces||[];for(const a of l){if(!(db.zones||[]).some(z=>z.id===a.zoneId)){e.acces=t.accZoneInconnue;break}if(!/^\d{4}-\d{2}-\d{2}$/.test(a.from||"")){e.acces=t.accDateInvalide;break}if(a.planId!=="aucun"&&!(db.aplans||[]).some(p=>p.id===a.planId)){e.acces=t.accPlanInconnu;break}}
if(!e.acces&&l.some((a,i)=>l.findIndex(b=>b.zoneId===a.zoneId&&b.from===a.from)!==i))e.acces=t.accDoublon}
}catch(x){}return e}})();
