/* « Appliquer » relève du droit « modifier » de l'écran (avant : aucune catégorie, un profil en lecture seule pouvait appliquer) */
(function(){const avant=categorieActe;categorieActe=function(act){return act==="accapply"?"modifier":avant(act)}})();
/* salariés de la sélection qui ont déjà, pour la zone, un changement daté après la date d'effet (il s'appliquera à sa date) */
function accProgrammes(pop,zoneId,d){return(pop||[]).filter(e=>(e.acces||[]).some(a=>a&&a.zoneId===zoneId&&a.from>d)).length}
function accLib(m){const z=(db.zones.find(x=>x.id===m.zoneDst)||{}).nom||"?",p=m.planDst==="aucun"?t.retirerAcces:(db.aplans.find(x=>x.id===m.planDst)||{}).nom||"?";return{z,p}}
function accConfirmTexte(n,m,d,prog){const L=accLib(m);return t.accConfirmDet.replace("{n}",n).replace("{z}",L.z).replace("{p}",L.p).replace("{d}",dateAff(d))+(prog?" "+t.accProgConf.replace("{k}",prog):"")}
function accAuditTexte(n,m,d){const L=accLib(m);return t.accAudit.replace("{n}",n).replace("{z}",L.z).replace("{p}",L.p).replace("{d}",dateAff(d))}
function accAvis(m,d,zone,plan,pop,SRV,AS){let h="";if(!peutFaire("modifier","acces"))h+='<div class="fw-hint">'+esc(t.accLecture)+"</div>";if(d<todayKey())h+='<div class="fw-err">'+esc(t.accDatePassee)+"</div>";
const prog=zone&&plan?(SRV?(AS||{}).programmes||0:accProgrammes(pop,m.zoneDst,d)):0;if(prog)h+='<div class="fw-hint" style="color:var(--warn,#a15c00)">'+esc(t.accProgAvis.replace("{k}",prog))+"</div>";return h}
