/* minutes occupées d'une journée (intervalles franchissant minuit découpés) */
function ivSegments(iv){const out=[];(iv||[]).forEach(p=>{let a=toMin(p.a),b=toMin(p.b);if(b===0)b=1440;if(b<=a){out.push([a,1440]);if(b>0)out.push([0,b])}else out.push([a,b])});return out.sort((x,y)=>x[0]-y[0])}
/* premier créneau libre : après le dernier intervalle (jusqu'à 4 h), sinon le premier trou de la journée */
function ivLibre(iv){const seg=ivSegments(iv);const hm=m=>m>=1440?"00:00":toHM(m);if(!seg.length)return{a:"08:00",b:"18:00"};const fin=Math.max(...seg.map(x=>x[1]));if(fin<1440&&!seg.some(x=>x[0]<=fin&&fin<x[1]))return{a:hm(fin),b:hm(Math.min(1440,fin+240))};let c=0;for(const x of seg){if(x[0]>c)return{a:hm(c),b:hm(Math.min(x[0],c+240))};c=Math.max(c,x[1])}return c<1440?{a:hm(c),b:hm(Math.min(1440,c+240))}:null}
