/* ===== correctif 14 : Pilotage › États (seconde analyse) ===== */
/* 3 — cache des blocs réellement réutilisé : la clé ne contient que ce qui change le calcul (plus le compteur de rendus,
   ni le nom ou les options d'affichage) ; langue incluse ; paramétrage de calcul et données suivis */
function etatCleCalcul(et){return[et.id,et.champs,et.periode,!!et.plage,et.ref,et.from,et.to,et.modele,!!et.simul,et.filtres||{},et.scope,!!et.aVenir]}
etatBlocsCache=function(et,opts,o){opts=opts||{};let sig="";try{sig=[db.arits,db.convs,db.reglesV,db.cals,db.jours,db.tt,db.feries].map(x=>JSON.stringify(x||[]).length).join(",")}catch(e){}
const cle=JSON.stringify([etatCleCalcul(et),opts.dept||"",opts.mat||"",ui.siteFilter||"",o,ui.lang,ETAT_GEN,window.__fwVer||0,typeof PTG_MODIF!=="undefined"?PTG_MODIF:0,typeof ABS_MODIF!=="undefined"?ABS_MODIF:0,todayKey(),sig,(db.emps||[]).length,(db.abs||[]).length,(db.corrections||[]).length,(db.ajust||[]).length,(db.ptg||[]).length]);
if(ETAT_CACHE&&ETAT_CACHE.cle===cle)return ETAT_CACHE.b;const b=etatBlocs(et,opts,o);ETAT_CACHE={cle,b};return b};
/* 11 — aperçu serveur : filtres et indicateurs dans la clé (sinon un aperçu périmé restait affiché comme à jour) */
etatApercuCle=function(e,opts){return JSON.stringify([etatCleCalcul(e),opts.dept||"",opts.mat||"",ui.siteFilter||"",ui.lang,todayKey()])};
/* 10, 12 — usage transmis au serveur (aperçu = lecture, impression, export) et langue des libellés */
etatSrvLancer=async function(et,opts,format,usage){const mm=etatBornesMinMax(et);
const r=await fetch("api/v1/travaux",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"etat",format,usage:usage||"",lang:ui.lang||"fr",etat:et,du:mm.du,au:mm.au,filtres:{dept:(opts||{}).dept||"",mat:(opts||{}).mat||"",site:ui.siteFilter||""}})});
if(r.status===401){apiSessionPerdue();throw new Error(t.svcErreur)}const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||t.svcErreur);return j};
etatServeur=async function(et,fmt,opts){if(ETAT_SRV_EN_COURS){flash(t.etSrvDeja,"warn");return}ETAT_SRV_EN_COURS=true;flash(t.grandEtat,"info");
try{const j=await etatSrvLancer(et,opts,fmt==="csv"?"csv":"blocs",fmt==="print"||fmt==="pdf"?"imprimer":"exporter");TRAVAUX_UI=null;const tr=await etatSrvAttendre(j,p=>flash(t.grandEtat+" "+p+" %","info"));if(!tr){flash(t.travLance,"info");return}
if(fmt==="csv"){const a=document.createElement("a");a.href="api/v1/travaux/"+tr.id+"/fichier";a.download="";document.body.appendChild(a);a.click();a.remove();flash(t.travFini.replace("{t}",tr.titre||et.nom||""),"ok");return}
const blocs=await etatSrvBlocs(tr);etatSortieLocale(fmt,et,etatMatriceDe(et,blocs))}catch(e){flash(e.message||t.svcErreur,"err")}finally{ETAT_SRV_EN_COURS=false}};
/* 13 — suivi de l'aperçu serveur sans voler le focus */
(function(){const r0=render;window.__etatRenduDoux=function(){try{if(typeof renderPreserve==="function")renderPreserve(()=>r0());else r0()}catch(e){r0()}}})();
/* indicateurs de la visualisation (moyenne, minimum, maximum) aussi dans Excel, le texte et l'impression */
(function(){const avant=etatMatriceDe;etatMatriceDe=function(et,blocs){const m=avant(et,blocs);const st=et.stats||{};if(!(st.moy||st.min||st.max))return m;
const detail=et.modele==="jour";const cols=et.champs.map(id=>db.arits.find(a=>a.id===id)).filter(Boolean);const fixed=detail?[et.colDate&&"date",et.colJour&&"jour",et.colBadge&&"badge"].filter(Boolean):[];
const nb=i=>blocs.map(b=>b.tot[i]).filter(v=>typeof v==="number"&&isFinite(v));const lg=(lib,fn)=>({cls:"tot",cells:[lib].concat(fixed.map(()=>"")).concat(cols.map((a,i)=>{const n=nb(i);return n.length?etatFmtTxt(fn(n),et,a):"—"}))});
if(st.moy)m.lignes.push(lg(t.etStatMoy,n=>n.reduce((x,y)=>x+y,0)/n.length));if(st.min)m.lignes.push(lg(t.etStatMin,n=>Math.min.apply(null,n)));if(st.max)m.lignes.push(lg(t.etStatMax,n=>Math.max.apply(null,n)));return m}})();
/* 14 — période entièrement à venir : signalée (heures réalisées encore inconnues) */
(function(){const avant=etatBornesTxt;etatBornesTxt=function(et){let s=avant(et);try{const L=etatBornesListe(et);if(et&&!et.simul&&L.length&&L.every(b=>b.du>todayKey()))s+=" · "+t.etAVenir}catch(e){}return s}})();
/* 5 — l'atelier suit le droit du serveur : créer, modifier, supprimer un état demandent le paramétrage des états (ETA) */
(function(){const avant=droitsEcran;droitsEcran=function(v,p){const r=avant(v,p);if((v||ui.view)!=="etats")return r;const pr=p===undefined?(SESS?profilCourant():null):p;
if(pr&&niveauProfil(pr)!=="admin"&&nivRang((pr.droits||{}).ETA)<4){r.creer=false;r.modifier=false;r.supprimer=false}return r}})();
/* 10 — matrice : actions de l'atelier = modification ; défilement et aperçu = lecture */
(function(){const avant=categorieActe;categorieActe=function(act){if(act==="et-aller"||act==="et-apercu-srv")return"";if(act&&act.indexOf("et-")===0)return"modifier";return avant(act)}})();
/* 7 — contrôles de saisie de l'atelier (mêmes règles que le serveur) */
(function(){const avant=champErreurs;champErreurs=function(ent,row){const e=avant(ent,row)||{};if(ent!=="etats"||!row)return e;
const nom=String(row.nom||"").trim();if(nom&&(db.etats||[]).some(x=>x.id!==row.id&&String(x.nom||"").trim().toLowerCase()===nom.toLowerCase()))e.nom=e.nom||t.etNomDoublon;
const inconnus=(row.champs||[]).filter(id=>!(db.arits||[]).some(a=>a.id===id));if(inconnus.length)e.champs=e.champs||t.etCptInconnu.replace("{n}",inconnus.length);
if(!PERIODS().concat([{v:"libre"}]).some(p=>p.v===row.periode))e.periode=t.etPerInconnue;
if(row.plage||row.periode==="libre"){const ok=k=>/^\d{4}-\d{2}-\d{2}$/.test(String(row[k]||""));if(!ok("from")||!ok("to"))e.from=t.etPlageDates;else if(row.from>row.to)e.to=t.etPlageInv;else{const d=dLoc(row.from),max=new Date(d.getFullYear()+3,d.getMonth(),d.getDate()-1);if(dLoc(row.to)>max)e.to=t.etPlage3}}
const fc=Object.keys(row.filtres||{}).filter(c=>row.filtres[c]&&!(db.champs||[]).some(x=>x.code===c));if(fc.length)e.filtres=t.etFiltreOrphelin.replace("{c}",fc.join(", "));return e}})();
/* 8, 9 — suppression : état cité par un profil refusé ; champ filtrant un état signalé (et refusé par le serveur) */
(function(){const avant=impactsDe;impactsDe=function(ent,row){const out=avant(ent,row)||[];try{if(ent==="etats"){const n=(db.profils||[]).filter(p=>Array.isArray(p.etats)&&p.etats.indexOf(row.id)>=0).length;if(n)out.push({n,texte:t.etImpProfils})}
if(ent==="champs"){const n=(db.etats||[]).filter(x=>x.filtres&&x.filtres[row.code]).length;if(n)out.push({n,texte:t.etImpChamp})}}catch(e){}return out}})();
(function(){const avant=delExecuter;delExecuter=function(){const c=delCible();if(c&&c.ent==="etats"){const p=(db.profils||[]).find(x=>Array.isArray(x.etats)&&x.etats.indexOf(c.row.id)>=0);if(p){ui.delConfirm=null;flash(t.etSupprProfil.replace("{p}",p.nom||p.id),"warn");return render()}}
if(c&&c.ent==="champs"){const x=(db.etats||[]).find(y=>y.filtres&&y.filtres[c.row.code]);if(x){ui.delConfirm=null;flash(t.etSupprChamp.replace("{e}",x.nom),"warn");return render()}}return avant.apply(this,arguments)}})();
Object.assign(T.fr,{etNomDoublon:"Un autre état porte déjà ce nom.",etCptInconnu:"{n} compteur(s) n'existe(nt) plus : retirez-les de l'état.",etPerInconnue:"Période inconnue.",etPlageDates:"Indiquez les dates de début et de fin de la plage.",etPlageInv:"La date de fin précède la date de début.",etPlage3:"Plage limitée à 3 ans.",etFiltreOrphelin:"Filtre sur un champ supprimé ({c}) : retirez-le.",etImpProfils:"profil(s) donnent accès à cet état",etImpChamp:"état(s) filtrent sur ce champ",etSupprProfil:"Cet état est cité par le profil « {p} » : retirez-le du profil (Administration › Profils) avant de le supprimer.",etSupprChamp:"Ce champ filtre l'état « {e} » : retirez ce filtre avant de supprimer le champ.",etAVenir:"période à venir : heures réalisées encore inconnues"});
Object.assign(T.en,{etNomDoublon:"Another report already has this name.",etCptInconnu:"{n} counter(s) no longer exist: remove them from the report.",etPerInconnue:"Unknown period.",etPlageDates:"Enter the start and end dates of the range.",etPlageInv:"The end date is before the start date.",etPlage3:"Range limited to 3 years.",etFiltreOrphelin:"Filter on a deleted field ({c}): remove it.",etImpProfils:"profile(s) give access to this report",etImpChamp:"report(s) filter on this field",etSupprProfil:"This report is listed in the profile “{p}”: remove it from the profile (Administration › Profiles) before deleting it.",etSupprChamp:"This field filters the report “{e}”: remove that filter before deleting the field.",etAVenir:"future period: worked hours not yet known"});
Object.assign(T.ar,{etNomDoublon:"توجد حالة أخرى بنفس الاسم.",etCptInconnu:"{n} عداد(ات) لم تعد موجودة: احذفها من الحالة.",etPerInconnue:"فترة غير معروفة.",etPlageDates:"أدخل تاريخي بداية ونهاية المدة.",etPlageInv:"تاريخ النهاية يسبق تاريخ البداية.",etPlage3:"المدة محدودة بثلاث سنوات.",etFiltreOrphelin:"تصفية على حقل محذوف ({c}): احذفها.",etImpProfils:"ملف(ات) تمنح النفاذ إلى هذه الحالة",etImpChamp:"حالة(ات) تُصفّي على هذا الحقل",etSupprProfil:"هذه الحالة مذكورة في الملف « {p} »: احذفها من الملف (الإدارة › الملفات) قبل حذفها.",etSupprChamp:"هذا الحقل يُصفّي الحالة « {e} »: احذف هذه التصفية قبل حذف الحقل.",etAVenir:"فترة قادمة: الساعات المنجزة غير معروفة بعد"});

/* ===== correctif 15 : Pilotage › Tableau de bord (seconde analyse) ===== */
/* 6, 8 — jours d'une demande : fiche trouvée par index, résultat mémorisé ; jours hors contrat non comptés ;
   demi-journée sur un jour non ouvré = 0 */
var NBJ_CACHE=null,NBJ_IDX=null;
nbJoursDmd=function(dm){const gen=(db.emps||[]).length+"|"+ETAT_GEN+"|"+(window.__fwVer||0);
if(!NBJ_CACHE||NBJ_CACHE.gen!==gen||NBJ_CACHE.emps!==db.emps){NBJ_CACHE={gen,emps:db.emps,m:new Map()};NBJ_IDX=new Map();(db.emps||[]).forEach(e=>{if(!e._leger)NBJ_IDX.set(String(e.mat),e)})}
const k=[dm.id,dm.mat,dm.tt,dm.du,dm.au,dm.demi?1:0,dm.hDeb,dm.hFin].join("|");if(NBJ_CACHE.m.has(k))return NBJ_CACHE.m.get(k);
const emp=NBJ_IDX.get(String(dm.mat));if(!emp)return null;let r;
if(ttHoraire(dm.tt))r=Math.round(dureeHeures(dm)/(Number(convFor(emp).baseJour)||8)*100)/100;
else{let du=dm.du,au=dm.au||dm.du;if(emp.entree&&du<emp.entree)du=emp.entree;if(emp.sortie&&au>emp.sortie)au=emp.sortie;const n=du&&au&&du<=au?joursOuvres(emp,du,au):0;r=dm.demi?(n?Math.max(.5,n-.5):0):n}
NBJ_CACHE.m.set(k,r);return r};
/* 12 — durées en heures : séparateur décimal et unité de la langue */
dureeTxt=function(dm){if(ttHoraire(dm.tt)){const h=dureeHeures(dm);return nbDec(Math.round(h*100)/100)+" "+t.bordH}const n=nbJoursDmd(dm);return n==null?"…":nbDec(n)+" "+t.jShort};
/* 3 — période par défaut (3 derniers mois) valide aussi en janvier et février */
bordEtat=function(){if(!ui.bordP){const n=new Date(),d=new Date(n.getFullYear(),n.getMonth()-2,1);ui.bordP={du:dkey(d.getFullYear(),d.getMonth(),1),au:todayKey()}}return ui.bordP};
/* 2, 5, 6, 14 — demandes décidées ou déposées sur la période servies par le serveur (absences anciennes comprises),
   avec le site et le nom des demandeurs ; une seule requête par période, échec mémorisé (bouton Réessayer) */
var BORD_SRV={cle:"",enCours:false,err:"",infos:{}};
bordChargerDmd=function(du){const P=bordEtat();if(!audSrv())return;const cle=P.du+"|"+P.au;if(BORD_SRV.cle===cle||BORD_SRV.enCours)return;BORD_SRV.enCours=true;BORD_SRV.err="";
fetch("api/v1/demandes/bord?du="+P.du+"&au="+P.au,{credentials:"same-origin",cache:"no-store"}).then(r=>r.json().then(j=>({r,j}))).then(({r,j})=>{BORD_SRV.enCours=false;BORD_SRV.cle=cle;if(r.status===401){apiSessionPerdue();return}if(!r.ok){BORD_SRV.err=j.message||("HTTP "+r.status);return render()}
const arr=db.dmd||(db.dmd=[]),idx=new Map(arr.map((x,i)=>[String(x&&x.id),i])),m=SYNC&&SYNC.colls&&SYNC.colls.dmd;
(j.dmd||[]).forEach(x=>{const id=String(x.id);if(!idx.has(id)){arr.push(x);if(m)m.set(id,JSON.stringify(x))}else{const i=idx.get(id),loc=arr[i];
/* version du serveur plus récente et copie locale non modifiée : remplacée */
if(m&&loc&&Number(x.__v||0)>Number(loc.__v||0)&&m.get(id)===JSON.stringify(loc)){arr[i]=x;m.set(id,JSON.stringify(x))}}});
Object.assign(BORD_SRV.infos,j.emps||{});NBJ_CACHE=null;render()}).catch(e=>{BORD_SRV.enCours=false;BORD_SRV.cle=cle;BORD_SRV.err=e.message;render()})};
/* 9 — date de décision : valideLe, à défaut la dernière décision de l'historique (données anciennes ou importées) */
function bordDecision(d){if(d.valideLe)return String(d.valideLe).slice(0,10);const h=(d.hist||[]).filter(x=>x&&(x.action==="accepte"||x.action==="refuse"));return h.length?String(h[h.length-1].d||"").slice(0,10):""}
function bordAnnulLe(d){const h=(d.hist||[]).filter(x=>x&&x.action==="annule");return h.length?String(h[h.length-1].d||"").slice(0,10):""}
var BORD_IDX=null;function bordEmp(mat){if(!BORD_IDX||BORD_IDX.emps!==db.emps||BORD_IDX.n!==(db.emps||[]).length){BORD_IDX={emps:db.emps,n:(db.emps||[]).length,m:new Map()};(db.emps||[]).forEach(e=>{if(!BORD_IDX.m.has(String(e.mat)))BORD_IDX.m.set(String(e.mat),e)})}return BORD_IDX.m.get(String(mat))||empVue(mat)}
function bordSiteDe(mat){const e=bordEmp(mat);return e&&e.siteId!==undefined?e.siteId:(BORD_SRV.infos[mat]||{}).siteId}
const bordNom2=d=>{const e=bordEmp(d.mat),i=BORD_SRV.infos[d.mat];return e?e.nom+" "+e.prenom:i?i.nom+" "+i.prenom:d.mat};
/* 1 — rectifications (modification ou annulation d'une demande acceptée) : jamais comptées comme de nouvelles demandes ;
   les annulations de la période ont leur indicateur ; 5 — demandes sans site connu signalées */
bordDmds=function(){const P=bordEtat(),p=dmdPerimetre();const dansP=d=>!p||p.has(d.mat);let horsSite=0;
const site=d=>{if(!ui.siteFilter)return true;const s=bordSiteDe(d.mat);if(s===undefined){horsSite++;return false}return s===ui.siteFilter};
const tous=(db.dmd||[]).filter(d=>d&&dansP(d)&&site(d));const dansPer=k=>!!k&&k>=P.du&&k<=P.au;const vraies=tous.filter(d=>!d.rectifDe);
return{P,horsSite,att:tous.filter(d=>etatDmd(d)==="attente").sort((a,b)=>a.creeLe<b.creeLe?-1:1),
acc:vraies.filter(d=>etatDmd(d)==="acceptee"&&dansPer(bordDecision(d))).sort((a,b)=>bordDecision(a)<bordDecision(b)?1:-1),
ref:vraies.filter(d=>etatDmd(d)==="refusee"&&dansPer(bordDecision(d))).sort((a,b)=>bordDecision(a)<bordDecision(b)?1:-1),
ann:vraies.filter(d=>etatDmd(d)==="annulee"&&dansPer(bordAnnulLe(d))),
rect:tous.filter(d=>d.rectifDe&&etatDmd(d)!=="attente"&&dansPer(bordDecision(d))),
crees:vraies.filter(d=>etatDmd(d)!=="annulee"&&dansPer(String(d.creeLe||"").slice(0,10)))}};
/* motif de refus (peut révéler une information de santé) : visible des seuls comptes qui valident les absences */
function bordMotifVisible(){return!SESS||(profilCourant()&&niveauProfil(profilCourant())==="admin")||nivRang(droit("ABS"))>=3}
const bordMotif=d=>bordMotifVisible()?motifRefusDe(d):"—";
const bordRect=d=>d.rectifDe?" ("+t.rectifTitre+")":"";
bordData=function(){const B=bordDmds();const etape=d=>{const c=db.circuits.find(x=>x.id===d.circuitId);return d.niveau+1+"/"+(c&&c.niveaux.length||0)+" — "+attenteDe(d)};const per=t.bordPeriode.replace("{d}",dateAff(B.P.du)).replace("{f}",dateAff(B.P.au));
return{att:{titre:t.enInstance,cols:[t.creeLe,t.mat,t.emp,t.typeDmd,t.periode,t.duree,t.etapeEnCours,t.anciennete],rows:B.att.map(d=>[dateAff(d.creeLe),d.mat,bordNom2(d),ttNom(d.tt)+bordRect(d),bordPer(d),dureeTxt(d),etape(d),bordAge(d)+" "+t.jShort])},
acc:{titre:t.histAcc+" — "+per,cols:[t.creeLe,t.valideLe,t.mat,t.emp,t.typeDmd,t.periode,t.duree,t.validePar],rows:B.acc.map(d=>[dateAff(d.creeLe),dateAff(bordDecision(d)),d.mat,bordNom2(d),ttNom(d.tt),bordPer(d),dureeTxt(d),d.validePar||""])},
ref:{titre:t.histRef+" — "+per,cols:[t.creeLe,t.refuseLe,t.mat,t.emp,t.typeDmd,t.periode,t.duree,t.refusePar,t.motif],rows:B.ref.map(d=>[dateAff(d.creeLe),dateAff(bordDecision(d)),d.mat,bordNom2(d),ttNom(d.tt),bordPer(d),dureeTxt(d),d.validePar||"",bordMotif(d)])},
B}};
function bordKpis(B){let jrs=0,hrs=0,inc=0;B.acc.forEach(d=>{if(ttHoraire(d.tt))hrs+=dureeHeures(d);else{const n=nbJoursDmd(d);if(n==null)inc++;else jrs+=n}});return{jrs:Math.round(jrs*100)/100,hrs:Math.round(hrs*100)/100,inc}}
/* 11 — exports : période, site, date d'édition et indicateurs en tête ; nom de fichier avec la période */
function bordEntete(B){const k=bordKpis(B);return[[t.bord],[t.periode,dateAff(B.P.du)+" → "+dateAff(B.P.au)],[t.site,ui.siteFilter?siteName(ui.siteFilter):t.tousSites||"—"],[t.editeLe,fmtD(new Date())],[t.bordKAtt,B.att.length],[t.bordKAcc,B.acc.length],[t.bordKRef,B.ref.length],[t.bordKAnn,B.ann.length],[t.jrsAccordes,nbDec(k.jrs)+(k.inc?" (+"+k.inc+" …)":"")],[t.bordH,nbDec(k.hrs)]]}
exportBordCsv=function(){const b=bordData(),lines=bordEntete(b.B).map(r=>csvLine(r));lines.push("");[b.att,b.acc,b.ref].forEach(sec=>{lines.push(csvLine([sec.titre]));lines.push(csvLine(sec.cols));sec.rows.forEach(r=>lines.push(csvLine(r)));lines.push("")});
download("demandes_"+b.B.P.du+"_"+b.B.P.au+(ui.siteFilter?"_"+String(siteName(ui.siteFilter)).replace(/[^\w\-]+/g,"_"):"")+".csv",lines.join("\r\n"))};
imprimerBord=function(pdf){const b=bordData();const tbl=sec=>"<h2>"+esc(sec.titre)+' <span class="pn">('+sec.rows.length+")</span></h2>"+'<table class="ptbl"><thead><tr>'+sec.cols.map((c,i)=>"<th"+(i>4?' class="r"':"")+">"+esc(c)+"</th>").join("")+"</tr></thead><tbody>"+(sec.rows.length?sec.rows.map(r=>"<tr>"+r.map((c,i)=>"<td"+(i>4?' class="r"':"")+">"+esc(c)+"</td>").join("")+"</tr>").join(""):'<tr><td colspan="'+sec.cols.length+'">'+esc(t.none)+"</td></tr>")+"</tbody></table>";
const zone=document.getElementById("fwprint");if(!zone)return;zone.innerHTML='<div class="pdoc"><div class="phead"><h1>'+esc(t.bord)+'</h1><div class="pmeta">'+esc(bordEntete(b.B).slice(1).map(r=>r[0]+" : "+r[1]).join(" · "))+"</div></div>"+tbl(b.att)+tbl(b.acc)+tbl(b.ref)+'<div class="pfoot">FIWAKTI</div></div>';
document.body.classList.add("printing");setTimeout(()=>{try{window.print()}catch(e){}setTimeout(()=>{document.body.classList.remove("printing");zone.innerHTML=""},400)},60);if(pdf)flash(t.pdfHint)};
viewBord=function(){const P=bordEtat();bordChargerDmd(P.du);try{dmdFichesCompleter()}catch(e){}const B=bordDmds(),K=bordKpis(B);
const kpi=(n,l,c,sub)=>'<div class="fw-kpi" style="--kc:'+c+'"><div class="v">'+n+'</div><div class="l">'+esc(l)+"</div>"+(sub?'<div class="fw-hint">'+esc(sub)+"</div>":"")+"</div>";
/* 10 — répartition : demandes déposées sur la période (annulées exclues), par type */
const parType={};B.crees.forEach(d=>{parType[ttNom(d.tt)]=(parType[ttNom(d.tt)]||0)+1});const tk=Object.keys(parType).sort((a,b)=>parType[b]-parType[a]);const mx=Math.max.apply(null,tk.map(k=>parType[k]).concat([1]));
const bars=tk.map(k=>'<div class="fw-bar"><span class="lb">'+esc(k)+'</span><span class="tr"><i style="width:'+parType[k]/mx*100+'%"></i></span><span class="vl fw-mono">'+parType[k]+"</span></div>").join("");
const MAXA=50,cel=(v,c)=>"<td"+(c?' class="'+c+'"':"")+">"+esc(v)+"</td>";
/* 13 — chaque ligne ouvre la demande dans l'écran Demandes */
const ouvrir=d=>'<td><button type="button" class="fw-lien" data-act="bord-dmd" data-id="'+esc(d.id)+'" aria-label="'+esc(t.bordOuvrir+" : "+bordNom2(d))+'">'+esc(bordNom2(d))+"</button></td>";
const ligneAtt=B.att.slice(0,MAXA).map(d=>{const age=bordAge(d),c=db.circuits.find(x=>x.id===d.circuitId);return"<tr>"+cel(dateAff(d.creeLe),"fw-mono")+ouvrir(d)+cel(ttNom(d.tt)+bordRect(d))+cel(bordPer(d),"fw-sm")+cel(dureeTxt(d),"fw-num")+'<td class="fw-sm">'+(d.niveau+1)+"/"+(c&&c.niveaux.length||0)+" — "+esc(attenteDe(d))+'</td><td class="fw-num'+(age>7?" fw-retard":"")+'">'+age+" "+esc(t.jShort)+"</td></tr>"}).join("");
const lAccRef=(l,avecMotif)=>l.slice(0,25).map(d=>"<tr>"+cel(dateAff(d.creeLe),"fw-mono")+cel(dateAff(bordDecision(d)),"fw-mono")+ouvrir(d)+cel(ttNom(d.tt))+cel(bordPer(d),"fw-sm")+cel(dureeTxt(d),"fw-num")+cel(d.validePar||"","fw-sm")+(avecMotif?cel(bordMotif(d),"fw-sm fw-muted"):"")+"</tr>").join("");
const plus=(n,tot)=>tot>n?'<div class="fw-hint" style="padding:8px 14px">'+esc(t.bordPlus.replace("{a}",n).replace("{n}",tot))+' <button class="fw-lien" data-act="go" data-view="dmd">'+esc(t.dmds)+"</button></div>":"";
const thAcc=(motif,lib)=>'<table class="fw-tbl"><thead><tr><th>'+esc(t.creeLe)+"</th><th>"+esc(lib)+"</th><th>"+esc(t.emp)+"</th><th>"+esc(t.typeDmd)+"</th><th>"+esc(t.periode)+'</th><th class="fw-num">'+esc(t.duree)+"</th><th>"+esc(motif?t.refusePar:t.validePar)+"</th>"+(motif?"<th>"+esc(t.motif)+"</th>":"")+"</tr></thead><tbody>";
const etatSrv=BORD_SRV.enCours?'<span class="fw-hint">'+esc(t.chargement||"…")+"</span>":BORD_SRV.err?'<span class="fw-tag warn">'+esc(BORD_SRV.err)+'</span> <button type="button" class="fw-btn sm" data-act="bord-reessayer">'+esc(t.bordReessayer)+"</button>":"";
const barreP='<div class="fw-card" style="padding:10px 14px;margin-bottom:12px"><div class="fw-u-row" style="gap:10px;flex-wrap:wrap;align-items:center"><strong class="fw-sm">'+esc(t.periode)+'</strong><label class="fw-sm">'+esc(t.fromL)+' <input type="date" data-bordk="du" value="'+esc(P.du)+'" aria-label="'+esc(t.periode+" — "+t.fromL)+'"></label><label class="fw-sm">'+esc(t.toL)+' <input type="date" data-bordk="au" value="'+esc(P.au)+'" aria-label="'+esc(t.periode+" — "+t.toL)+'"></label>'+etatSrv+'<span class="fw-hint">'+esc(t.bordNoteP)+"</span></div>"+(B.horsSite?'<div class="fw-hint" style="margin-top:6px">'+esc(t.bordHorsSite.replace("{n}",B.horsSite))+"</div>":"")+"</div>";
const carte=h=>'<div class="fw-card" style="overflow-x:auto">'+h+"</div>";
return hero({title:t.bord,lede:t.ledeBord,search:false,actions:'<button class="fw-btn" data-act="bordcsv">'+esc(t.exportExcel)+'</button><button class="fw-btn" data-act="bordpdf">PDF</button><button class="fw-btn" data-act="bordprint">'+esc(t.imprimer)+"</button>"})+barreP
+'<div class="fw-kpis">'+kpi(B.att.length,t.bordKAtt,"#b45309",t.bordAuj)+kpi(B.acc.length,t.bordKAcc,"#0f766e",t.bordSurDec)+kpi(B.ref.length,t.bordKRef,"#c2410c",t.bordSurDec)+kpi(B.ann.length,t.bordKAnn,"#8b9995",t.bordSurP)
+kpi(nbDec(K.jrs)+(K.inc?" +"+K.inc+" …":""),t.jrsAccordes,"#12645f",(K.hrs?t.bordHeures.replace("{h}",nbDec(K.hrs))+" · ":"")+t.bordJrsDec)+"</div>"
+(B.rect.length?'<div class="fw-hint" style="margin:6px 0 10px">'+esc(t.bordRectN.replace("{n}",B.rect.length))+"</div>":"")
+'<div class="fw-split">'+carte('<div class="fw-cardh">'+esc(t.enInstance)+'</div><table class="fw-tbl"><thead><tr><th>'+esc(t.creeLe)+"</th><th>"+esc(t.emp)+"</th><th>"+esc(t.typeDmd)+"</th><th>"+esc(t.periode)+'</th><th class="fw-num">'+esc(t.duree)+"</th><th>"+esc(t.etapeEnCours)+'</th><th class="fw-num">'+esc(t.anciennete)+"</th></tr></thead><tbody>"+(ligneAtt||'<tr><td colspan="7"><div class="fw-empty">'+esc(t.rienEnInstance)+"</div></td></tr>")+"</tbody></table>"+plus(MAXA,B.att.length))
+'<div class="fw-panel"><h3>'+esc(t.bordParType)+'</h3><div class="body">'+(bars||'<div class="fw-hint">'+esc(t.none)+"</div>")+"</div></div></div>"
+'<div style="margin-top:16px">'+carte('<div class="fw-cardh">'+esc(t.histAcc)+"</div>"+thAcc(false,t.valideLe)+(lAccRef(B.acc,false)||'<tr><td colspan="7"><div class="fw-empty">'+esc(t.none)+"</div></td></tr>")+"</tbody></table>"+plus(25,B.acc.length))+"</div>"
+'<div style="margin-top:16px">'+carte('<div class="fw-cardh">'+esc(t.histRef)+"</div>"+thAcc(true,t.refuseLe)+(lAccRef(B.ref,true)||'<tr><td colspan="8"><div class="fw-empty">'+esc(t.none)+"</div></td></tr>")+"</tbody></table>"+plus(25,B.ref.length))+"</div>"
+'<div class="fw-note">'+esc(t.noteBord)+"</div>"};
document.addEventListener("click",function(ev){const el=ev.target&&ev.target.closest?ev.target.closest('[data-act="bord-dmd"],[data-act="bord-reessayer"]'):null;if(!el)return;ev.stopPropagation();ev.preventDefault();
if(el.dataset.act==="bord-reessayer"){BORD_SRV.cle="";return render()}const dm=(db.dmd||[]).find(x=>String(x.id)===String(el.dataset.id));if(!dm)return;ui.view="dmd";ui.q="";selCharger(dm);render()},true);
