/* ===== correctif 16 : Pilotage › Journal (seconde analyse) ===== */
var PUT_DEPT_DEJA_HORS=false;
(function(){const avant=put;put=function(key,row){PUT_DEPT_DEJA_HORS=false;if(key==="depts"&&row){const a=(db.depts||[]).find(d=>d.id===row.id);PUT_DEPT_DEJA_HORS=!!(a&&a.type==="hors")}try{return avant.apply(this,arguments)}finally{PUT_DEPT_DEJA_HORS=false}}})();
/* 3 — règles automatiques : chaque action est journalisée avec son résultat (faite, sans effet, refusée faute de droit,
   en échec) ; une action que le serveur refuserait (droit insuffisant) n'est plus exécutée ni annoncée comme faite */
const ACT_DROIT={desac_compte:["SYS",4],desac_portail:["EMP",2],bloquer_badge:["EMP",2],retirer_acces:["EMP",2],retirer_bio:["TER",2],archiver:["EMP",2]};
function regleDroitOk(a){const d=ACT_DROIT[a];if(!d||!SESS)return true;const pr=profilCourant();if(!pr||niveauProfil(pr)==="admin")return true;return nivRang(droit(d[0]))>=d[1]}
appliquerRegles=function(declencheur,emp,meta){if(!emp||!Array.isArray(db.regles))return[];const faits=[];const actor=typeof moi==="function"&&moi()?moi().nom:"système";
db.regles.filter(r=>r.actif&&r.declencheur===declencheur).forEach(r=>{const acts=r.actions||[];if(!acts.length)return;const fait=[],sans=[],refus=[],echec=[];
acts.forEach(a=>{if(!regleDroitOk(a)){refus.push(a);return}try{const lab=a==="maj_workflows"?null:executerAction(a,emp,meta||{});(lab?fait:sans).push(a)}catch(e){echec.push(a);console.error("regle action",a,e)}});
const entry={id:uid("je"),declencheur,regleId:r.id,regleNom:r.nom,mat:emp.mat,employe:(emp.nom||"")+" "+(emp.prenom||""),codes:fait,sansEffet:sans,refuses:refus,echecs:echec,actions:fait.map(actLabel),par:actor,detail:(meta&&meta.detail)||""};
journalPush(entry);faits.push(entry)});return faits};
/* 12 — affichage dans la langue de l'écran : actions par code, statuts, événements du serveur */
journalNorm=(function(avant){return function(j){const n=avant(j);j=j||{};if(Array.isArray(j.codes))n.actions=j.codes.map(actLabel);
const st=[[j.sansEffet,t.jSansEffet],[j.refuses,t.jRefusees],[j.echecs,t.jEchecs]].filter(x=>Array.isArray(x[0])&&x[0].length).map(x=>x[1]+" : "+x[0].map(actLabel).join(", "));
if(st.length)n.detail=(n.detail?n.detail+" · ":"")+st.join(" · ");
if(j.type==="systeme"){n.typeLib=t.journalSysteme;if(j.code==="sortie_non_traitee")n.objet=t.jSortieNonTraitee.replace("{d}",dateAff(j.sortie||""))}
if(!n.typeLib&&!j.regleId)n.typeLib=t.journalAutre;return n}})(journalNorm);
function journalGarde(j,A){if(A.mat&&String(j.mat||"")!==String(A.mat))return false;if(A.nature){if(A.nature==="regle")return!!j.regleId;return j.type===A.nature}return true}
function journalFiltres(A){const nat=[["",t.tous||"Tous"],["regle",t.journalRegles],["import",t.journalImport],["home",t.journalAccueil],["systeme",t.journalSysteme]];
return'<div class="fw-u-row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-top:6px"><label class="fw-sm">'+esc(t.journalNature)+' <select data-jnat aria-label="'+esc(t.journalNature)+'">'+nat.map(x=>'<option value="'+x[0]+'"'+((A.nature||"")===x[0]?" selected":"")+">"+esc(x[1])+"</option>").join("")+"</select></label>"
+'<label class="fw-sm">'+esc(t.mat)+' <input data-jmat value="'+esc(A.mat||"")+'" size="10" aria-label="'+esc(t.mat)+'"></label>'+(A.mat||A.nature?'<button type="button" class="fw-lien" data-act="journal-sansfiltre">'+esc(t.etEffacerFiltres)+"</button>":"")+"</div>"}
document.addEventListener("change",function(ev){const el=ev.target;if(!el||!el.dataset)return;if(el.dataset.jnat===undefined&&el.dataset.jmat===undefined)return;ev.stopPropagation();const A=audEtat();if(el.dataset.jnat!==undefined)A.nature=el.value;else A.mat=String(el.value||"").trim();A.off.jrn=0;render()},true);
document.addEventListener("click",function(ev){const el=ev.target&&ev.target.closest?ev.target.closest('[data-act="journal-sansfiltre"]'):null;if(!el)return;ev.stopPropagation();ev.preventDefault();const A=audEtat();A.nature="";A.mat="";A.off.jrn=0;render()},true);
