var EMP_IDX={L:null,n:-1,m:null};function empParId(id){const L=db.emps||[];if(EMP_IDX.L!==L||EMP_IDX.n!==L.length){const m=new Map();L.forEach(e=>{if(e&&e.id!==undefined)m.set(e.id,e)});EMP_IDX={L,n:L.length,m}}return EMP_IDX.m.get(id)||null}
var U_IDX={L:null,n:0,t:0,emp:new Set,log:new Set};function usrIdx(){const L=db.users||[];if(U_IDX.L!==L||U_IDX.n>L.length||Date.now()-U_IDX.t>2000){U_IDX={L,n:0,t:Date.now(),emp:new Set,log:new Set}}while(U_IDX.n<L.length){const u=L[U_IDX.n++];if(u){if(u.empId)U_IDX.emp.add(u.empId);U_IDX.log.add(String(u.login||"").trim().toLowerCase())}}return U_IDX}
function cptSrvMode(){return typeof LIC!=="undefined"&&!!LIC.serveur&&!DEMO&&!!SESS}
/* états lus sur le serveur (seul juge des mots de passe) pour les comptes affichés, par lots */
var CPT_SRV={m:new Map(),att:new Set(),enCours:false,t:0,res:null,resT:0};
function cptSrvOublier(u){if(u)CPT_SRV.m.delete(String(u.login||"").trim().toLowerCase())}
function cptSrvDemander(l){if(!cptSrvMode()||!l)return;l=String(l).trim().toLowerCase();if(CPT_SRV.m.has(l)||CPT_SRV.att.has(l))return;CPT_SRV.att.add(l);if(!CPT_SRV.enCours)setTimeout(cptSrvLot,30)}
function cptSrvLot(){if(CPT_SRV.enCours||!CPT_SRV.att.size)return;const l=Array.from(CPT_SRV.att).slice(0,400);l.forEach(x=>CPT_SRV.att.delete(x));CPT_SRV.enCours=true;
fetch("api/v1/comptes?logins="+encodeURIComponent(l.join(",")),{credentials:"same-origin"}).then(r=>r.ok?r.json():{comptes:[]}).then(j=>{l.forEach(x=>CPT_SRV.m.set(x,null));(j.comptes||[]).forEach(c=>CPT_SRV.m.set(String(c.login).toLowerCase(),c));CPT_SRV.t=Date.now()}).catch(()=>{}).then(()=>{CPT_SRV.enCours=false;if(CPT_SRV.att.size)cptSrvLot();else try{render()}catch(e){}})}
function cptSrvCharger(){if(!cptSrvMode())return;if(Date.now()-CPT_SRV.t>60000&&!CPT_SRV.enCours&&CPT_SRV.m.size){CPT_SRV.m=new Map}(db.users||[]).forEach(u=>{if(estCompteGestion(u)||(ui.sel&&ui.sel.id===u.id))cptSrvDemander(u.login)});cptSrvResume()}
function cptSrvRow(u){if(!cptSrvMode()||!u||!u.login)return undefined;const l=String(u.login).trim().toLowerCase();if(!CPT_SRV.m.has(l)){cptSrvDemander(l);return undefined}return CPT_SRV.m.get(l)}
function cptSrvEtat(u){const c=cptSrvRow(u);if(!c)return"";const e=u.empId?empParId(u.empId):null;if(e&&e.sortie&&e.sortie<=todayKey())return"sorti";if(!Number(c.actif)||u.actif===false)return"desactive";if(c.verrou&&new Date(c.verrou).getTime()>Date.now())return"verrouille";if(c.etat==="sans_mdp")return"invite";if(c.etat==="temp_matricule"||c.etat==="temp_code")return"premiere";if(Number(c.changer))return"achanger";return"actif"}
function cptDerniere(u){const c=cptSrvRow(u);if(c)return c.derniere?dateAff(String(c.derniere).slice(0,10))+" "+new Date(c.derniere).toLocaleTimeString(ui.lang==="ar"?"ar-TN":ui.lang==="en"?"en-GB":"fr-FR",{hour:"2-digit",minute:"2-digit"}):"";return cptSrvMode()?"":u.derniereConx?dateAff(u.derniereConx):""}
function cptSrvResume(){if(!cptSrvMode()||Date.now()-CPT_SRV.resT<60000)return;CPT_SRV.resT=Date.now();fetch("api/v1/comptes?resume=1",{credentials:"same-origin"}).then(r=>r.ok?r.json():null).then(j=>{if(j&&j.resume){CPT_SRV.res=j.resume;ETATS_CPT={}}}).catch(()=>{})}
/* compteurs : ceux du serveur ; salariés sortis encore actifs comptés avec l'index des salariés */
var etatsComptes0=etatsComptes;etatsComptes=function(){if(!cptSrvMode())return etatsComptes0();if(typeof profilCourant==="function"&&profilCourant()&&niveauProfil(profilCourant())!=="admin")return{invite:0,verrouille:0,sortiActif:0};cptSrvResume();const L=db.users||[],cle=Math.floor(Date.now()/5000)+"|"+L.length+"|"+todayKey()+"|"+JSON.stringify(CPT_SRV.res);if(ETATS_CPT.cle===cle&&ETATS_CPT.L===L)return ETATS_CPT;const j=todayKey();let so=0;L.forEach(u=>{if(u&&u.actif!==false&&u.empId){const e=empParId(u.empId);if(e&&e.sortie&&e.sortie<=j)so++}});ETATS_CPT={cle,L,invite:(CPT_SRV.res||{}).invite||0,verrouille:(CPT_SRV.res||{}).verrouille||0,sortiActif:so};return ETATS_CPT};
/* actions du serveur : changement imposé, déverrouillage */
function cptSrvAction(a,u,ok){fetch("api/v1/comptes/"+a,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF":(SESS||{}).csrf||""},body:JSON.stringify({login:u.login})}).then(x=>x.json().then(j=>({x,j}))).then(({x,j})=>{if(!x.ok){flash(j.message||j.erreur||t.svcErreur,"err");return}cptSrvOublier(u);CPT_SRV.resT=0;flash(ok,"ok");cptSrvDemander(u.login)}).catch(()=>flash(t.svcAbsent,"err"))}
