document.addEventListener("click",function(ev){const el=ev.target&&ev.target.closest?ev.target.closest('[data-act="cir-haut"],[data-act="cir-bas"]'):null;if(!el||!ui.sel)return;ev.stopPropagation();ev.preventDefault();if(SESS&&!peutFaire("modifier","circuits")){flash(t.refusActe.replace("{a}",t.acte_modifier),"warn");return}const L=db.circuits||[],i=L.findIndex(x=>x.id===ui.sel.id),j=i+(el.dataset.act==="cir-haut"?-1:1);if(i<0||j<0||j>=L.length)return;const x=L[i];L[i]=L[j];L[j]=x;save();flash(t.saved,"ok");render()},true);
