/* trousseau : mot de passe (et code de double authentification) redemandés ; clé de l'audit seulement sur demande */
function sysTrousseauDialogue(){const fond=document.createElement("div");fond.className="fw-modal-fond";fond.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center";
const d=document.createElement("div");d.setAttribute("role","dialog");d.setAttribute("aria-modal","true");d.setAttribute("aria-labelledby","trsT");d.className="fw-card fw-u-p-lg";d.style.cssText="max-width:440px;width:92%;background:var(--surface,#fff)";
d.innerHTML='<h3 id="trsT" style="margin-top:0">'+esc(t.regTrousseauT)+'</h3><p class="fw-hint">'+esc(t.regTrousseauConf)+"</p>"+field(t.trsMdp,'<input type="password" id="trsMdp" autocomplete="current-password">')+field(t.trsCode,'<input id="trsCode" inputmode="numeric" maxlength="7" autocomplete="one-time-code">',t.trsCodeH)+'<label class="fw-check"><input type="checkbox" id="trsAudit"> <span>'+esc(t.trsAudit)+'</span></label><div class="fw-hint">'+esc(t.trsAuditH)+'</div><div class="fw-u-row" style="gap:8px;margin-top:12px;justify-content:flex-end"><button type="button" class="fw-btn" data-trs="non">'+esc(t.annuler||"Annuler")+'</button><button type="button" class="fw-btn pri" data-trs="oui">'+esc(t.sysTelecharger)+"</button></div>";
fond.appendChild(d);document.body.appendChild(fond);const fermer=()=>{fond.remove()};setTimeout(()=>{const i=d.querySelector("#trsMdp");if(i)i.focus()},30);
fond.addEventListener("keydown",e=>{if(e.key==="Escape")fermer()});d.addEventListener("click",e=>{const b=e.target.closest("[data-trs]");if(!b)return;if(b.dataset.trs==="non")return fermer();
const corps={mdp:d.querySelector("#trsMdp").value,code:d.querySelector("#trsCode").value,audit:d.querySelector("#trsAudit").checked};b.disabled=true;
fetch("api/v1/systeme/cle-sauvegarde",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(corps)}).then(x=>x.text().then(txt=>({x,txt}))).then(({x,txt})=>{b.disabled=false;if(!x.ok){let m=t.svcErreur||"Erreur";try{m=JSON.parse(txt).message||m}catch(e){}flash(m,"err");return}fermer();download("fiwakti-trousseau-"+((ui.sysReg||{}).cle||"")+".key",txt);flash(t.trsOk,"ok")}).catch(e=>{b.disabled=false;flash(e.message,"err")})})}
