/* ===== correctif 29 : Administration › Licences et modules ===== */
var LIC_EMPREINTE="",LIC_CAPA=null,LIC_EMP_T=0;
function licEmpreinteCharger(){if(!(typeof LIC!=="undefined"&&LIC.serveur)||DEMO||Date.now()-LIC_EMP_T<60000)return;LIC_EMP_T=Date.now();fetch("api/v1/modules",{credentials:"same-origin",cache:"no-store"}).then(r=>r.ok?r.json():null).then(j=>{if(!j)return;const a=LIC_EMPREINTE+"|"+JSON.stringify(LIC_CAPA);LIC_EMPREINTE=j.empreinte||"";LIC_CAPA=j.capacite||null;if(a!==LIC_EMPREINTE+"|"+JSON.stringify(LIC_CAPA))try{render()}catch(e){}}).catch(()=>{})}
function licCapaciteHTML(){licEmpreinteCharger();const c=LIC_CAPA;if(!c)return"";if(!c.max)return'<div class="fw-hint">'+esc(t.licCapaIllimitee.replace("{n}",c.utilise))+"</div>";const pc=Math.round(100*c.utilise/c.max);return'<div class="fw-hint"'+(pc>=95?' style="color:var(--danger)"':"")+">"+esc(t.licCapacite.replace("{n}",c.utilise).replace("{m}",c.max).replace("{p}",pc))+"</div>"}
function licModulesTxt(){const l=Array.isArray(LIC.fw)&&LIC.fw.length?LIC.fw.filter(x=>x!=="FW-Core"&&x!=="FW-RH"):null;if(!l)return modNoms();return l.map(x=>t["modN_"+x]||x).join(", ")||"—"}
/* dialogue de confirmation : Échap ferme, Tab reste dans la fenêtre, le focus revient à l'élément d'origine */
var fwConfirm0=fwConfirm;fwConfirm=function(opts,cb){const orig=document.activeElement;return fwConfirm0(opts,function(){try{if(cb)cb.apply(this,arguments)}finally{setTimeout(()=>{try{if(orig&&document.contains(orig))orig.focus()}catch(e){}},30)}})};
document.addEventListener("keydown",function(ev){if(!ui.fwConfirm)return;const d=document.querySelector('[role="dialog"],[role="alertdialog"]');if(!d)return;if(ev.key==="Escape"){const b=d.querySelector(".foot button");if(b){ev.preventDefault();b.click()}return}if(ev.key==="Tab"){const f=[...d.querySelectorAll("button,input,textarea,select,[tabindex]:not([tabindex='-1'])")].filter(x=>!x.disabled);if(!f.length)return;const i=f.indexOf(document.activeElement);if(ev.shiftKey&&(i<=0)){ev.preventDefault();f[f.length-1].focus()}else if(!ev.shiftKey&&(i===f.length-1||i<0)){ev.preventDefault();f[0].focus()}}},true);
Object.assign(T.fr,{licH:"La licence est signée par l'éditeur et liée à cette installation (empreinte ci-dessus). Elle fixe les modules ouverts, la capacité (nombre de salariés actifs) et, le cas échéant, son échéance ; une restauration de sauvegarde ne la modifie pas.",licProgFutur:"La licence prendra effet le {d} (licence actuelle conservée jusque-là).",licApercuEchue:"Cette licence est déjà échue : l'installation passerait en « {e} ».",licCapacite:"Capacité : {n} salariés actifs sur {m} autorisés ({p} %)",licCapaIllimitee:"Capacité : {n} salariés actifs (sans limite)",licEmpreinte:"Empreinte de cette installation (à communiquer au fournisseur)",licBloqueeTxt:"Votre licence FIWAKTI est bloquée : l'application n'est plus accessible. Un administrateur doit saisir une nouvelle clé ; vos données restent conservées.",modDepActifs:"Désactivez d'abord : {m}",modDepInactives:"Activez d'abord : {m}"});
