Object.assign(MENU_NIVEAU,{valj:"avance",feries:"rh",biorh:"rh",rgv:"rh",champs:"admin",cloture:"rh"});
/* affichages lus de façon sûre : un élément mal formé est écarté au lieu de bloquer l'application */
affichages=function(){return(Array.isArray(db.affichages)?db.affichages:[]).filter(a=>a&&typeof a==="object"&&typeof a.id==="string"&&a.id).map(a=>{if(!Array.isArray(a.ecrans))a.ecrans=[];if(typeof a.nom!=="string")a.nom=String(a.nom==null?a.id:a.nom).slice(0,60);return a})};
/* choix mémorisé devenu invalide → affichage par défaut du profil (au lieu d'aucun) */
affichageActif=function(){const p=SESS?profilCourant():null;let choix=ui.affichageChoix;if(choix===undefined){try{choix=localStorage.getItem(affichageCle())}catch(e){choix=null}}const aut=affichagesAutorises();
const parDefaut=()=>{const d=p&&p.affichages&&String(p.affichages.defaut||"");if(d&&d.indexOf("aff:")===0){const a=affichages().find(x=>x.id===d.slice(4));if(a&&(!SESS||aut.indexOf(a)>=0))return a}return null};
if(choix==="")return null;if(choix===null||choix===undefined)return parDefaut();const a=affichages().find(x=>x.id===choix);if(a&&aut.indexOf(a)>=0)return a;return parDefaut()};
/* éditeur : les modifications portent sur un brouillon, écrit seulement à l'enregistrement (avant : écrit aussitôt,
   envoyé au serveur à la sauvegarde suivante, même sans clic sur Enregistrer) */
affichageEdite=function(){return ui.affBrouillon||null};
function affSale(){const b=ui.affBrouillon;if(!b)return false;return ui.affOrig===null||JSON.stringify({nom:b.nom,ecrans:b.ecrans})!==ui.affOrig}
function affCharger(a,nouveau){ui.affBrouillon=a?{id:a.id,nom:String(a.nom||""),ecrans:(a.ecrans||[]).slice()}:null;ui.affSel=a?a.id:null;ui.affOrig=a&&!nouveau?JSON.stringify({nom:ui.affBrouillon.nom,ecrans:ui.affBrouillon.ecrans}):null}
estSale=(function(avant){return function(){if(ui.view==="affmenu"&&affSale())return true;return avant()}})(estSale);
quitterExecuter=(function(avant){return function(garder){if(!garder&&ui.view==="affmenu")affCharger(null);return avant(garder)}})(quitterExecuter);
function affGroupeDe(v){const g=MENU_GROUPES().find(x=>x[1].indexOf(v)>=0);return g?g[1]:[]}
function affProposes(){return MENU_GROUPES().map(g=>[g[0],g[1].filter(v=>typeof vueModuleActive!=="function"||vueModuleActive(v))]).filter(g=>g[1].length)}
ecransDuNiveau=function(niv){const r=NIV_UI_RANG[niv]||0;return affProposes().reduce((l,g)=>l.concat(g[1].filter(v=>NIV_UI_RANG[MENU_NIVEAU[v]||"admin"]<=r)),[])};
function affFocus(sel){setTimeout(()=>{const e=document.querySelector(sel);if(e)try{e.focus()}catch(x){}},0)}
viewAffichages=function(){const L=affichages(),b=affichageEdite(),dr=SESS?droitsEcran("affmenu"):{creer:true,modifier:true,supprimer:true};
const util=id=>(db.profils||[]).filter(p=>p&&p.affichages&&(p.affichages.defaut==="aff:"+id||(Array.isArray(p.affichages.autorises)?p.affichages.autorises:[]).indexOf(id)>=0));
const liste='<div class="fw-card fw-u-p" style="margin-bottom:12px"><div class="fw-u-row" style="gap:8px;align-items:center;flex-wrap:wrap">'+(L.length?L.map(x=>'<button type="button" class="fw-btn sm'+(b&&b.id===x.id?" pri":"")+'" data-act="aff-ouvrir" data-id="'+esc(x.id)+'" aria-pressed="'+(b&&b.id===x.id?"true":"false")+'">'+esc(x.nom)+' <span class="fw-hint">· '+esc(t.affTip.replace("{n}",x.ecrans.length))+" · "+esc(t.affUtilise.replace("{n}",util(x.id).length))+"</span></button>").join(""):'<span class="fw-hint">'+esc(t.affAucun)+"</span>")+'<div class="fw-spacer"></div><button type="button" class="fw-btn pri" data-act="aff-nouveau"'+(dr.creer?"":" disabled")+">"+ICO_PLUS+"<span>"+esc(t.affNouveau)+"</span></button></div></div>";
let edit="";if(b){const ro=!dr.modifier&&!(ui.affOrig===null&&dr.creer),choisis=b.ecrans,nouveau=!L.some(x=>x.id===b.id),dis=ro?" disabled":"";
const grille=affProposes().map((g,gi)=>{const n=g[1].filter(v=>choisis.indexOf(v)>=0).length;return'<fieldset class="fw-aff-groupe"><legend class="gh"><label class="fw-check"><input type="checkbox" data-affgroupe="'+gi+'"'+(n===g[1].length?" checked":"")+(n>0&&n<g[1].length?' data-mixte="1"':"")+dis+"> <span>"+esc(g[0])+'</span></label> <span class="fw-hint">'+esc(t.affGroupeN.replace("{n}",n).replace("{t}",g[1].length))+"</span></legend>"+
g[1].map(v=>{const on=choisis.indexOf(v)>=0,dans=choisis.filter(x=>g[1].indexOf(x)>=0),k=dans.indexOf(v);return'<div class="fw-aff-ecran"><label class="fw-check"><input type="checkbox" data-affecran="'+esc(v)+'" aria-describedby="affN_'+esc(v)+'"'+(on?" checked":"")+dis+"> <span>"+esc(libelleVue(v))+'</span></label> <span class="fw-hint" id="affN_'+esc(v)+'">'+esc(t["niv_"+(MENU_NIVEAU[v]||"admin")])+"</span>"+(on&&!ro?'<span class="fw-aff-ordre"><button type="button" class="fw-iconb" data-act="aff-monter" data-v="'+esc(v)+'" aria-label="'+esc(t.affMonter+" : "+libelleVue(v))+'"'+(k<=0?" disabled":"")+'>↑</button><button type="button" class="fw-iconb" data-act="aff-descendre" data-v="'+esc(v)+'" aria-label="'+esc(t.affDescendre+" : "+libelleVue(v))+'"'+(k<0||k>=dans.length-1?" disabled":"")+">↓</button></span>":"")+"</div>"}).join("")+"</fieldset>"}).join("");
const apercu=affProposes().map(g=>{const l=b.ecrans.filter(v=>g[1].indexOf(v)>=0);return l.length?"<li><strong>"+esc(g[0])+"</strong> : "+l.map(v=>esc(libelleVue(v))).join(" · ")+"</li>":""}).join("");
const us=util(b.id);
edit='<div class="fw-card fw-u-p-lg">'+(ro?'<div class="fw-note">'+esc(t.affLecture)+"</div>":"")+(affSale()?'<div class="fw-note warn" role="status">'+esc(nouveau?t.affNonEnreg:t.affModifNonEnreg)+"</div>":"")+'<div class="fw-row2">'+field(t.affNom,'<input id="affNom" value="'+esc(b.nom)+'" maxlength="60"'+dis+">")+'<div class="fw-f"><span class="fw-lbl" id="affNivL">'+esc(t.affDepuis)+'</span><div class="fw-u-row" style="gap:6px;flex-wrap:wrap" role="group" aria-labelledby="affNivL">'+NIV_UI.map(n=>'<button type="button" class="fw-btn sm" data-act="aff-niveau" data-niv="'+n+'"'+dis+">"+esc(t["niv_"+n])+"</button>").join("")+"</div></div></div>"+
'<div class="fw-sec">'+esc(t.affEcrans)+' <span class="fw-hint">— '+esc(t.affApercu.replace("{n}",choisis.length))+'</span></div><div class="fw-aff-grille">'+grille+"</div>"+
'<div class="fw-sec">'+esc(t.affApercuT)+'</div>'+(apercu?'<ul class="fw-hint" style="margin:4px 0 8px;padding-inline-start:18px">'+apercu+"</ul>":'<p class="fw-hint">'+esc(t.affVide)+"</p>")+'<p class="fw-hint">'+esc(t.affToujours)+"</p>"+(us.length?'<p class="fw-hint">'+esc(t.affProfilsUtil.replace("{l}",us.map(p=>p.nom).join(", ")))+"</p>":"")+
'<div class="fw-u-row" style="gap:8px;margin-top:12px;justify-content:flex-end;flex-wrap:wrap">'+(!nouveau&&dr.supprimer?'<button type="button" class="fw-btn dgr" data-act="aff-supprimer">'+esc(t.del)+"</button>":"")+(!nouveau&&dr.creer?'<button type="button" class="fw-btn" data-act="aff-dupliquer">'+esc(t.affDupliquer)+"</button>":"")+'<button type="button" class="fw-btn" data-act="aff-annuler">'+esc(t.cancel||t.annuler||"Annuler")+'</button><button type="button" class="fw-btn pri" data-act="aff-enregistrer"'+(ro?" disabled":"")+">"+esc(t.save)+"</button></div></div>"}
return hero({title:t.affTitre,count:L.length,lede:t.affLede,search:false})+liste+edit};
VIEWS.affmenu=()=>viewAffichages();
render=(function(avant){return function(){const r=avant.apply(this,arguments);try{if(ui.view==="affmenu")document.querySelectorAll("[data-affgroupe][data-mixte]").forEach(c=>{c.indeterminate=true})}catch(e){}return r}})(render);
function affLecture(acte){if(!SESS)return false;const d=droitsEcran("affmenu");if(acte==="modifier"&&ui.affOrig===null&&d.creer)return false;return!d[acte]}
document.addEventListener("input",function(ev){const el=ev.target;if(!el||el.id!=="affNom"||!ui.affBrouillon)return;ui.affBrouillon.nom=el.value},true);
document.addEventListener("change",function(ev){const el=ev.target;if(!el||!el.dataset||ui.view!=="affmenu")return;const b=ui.affBrouillon;if(el.dataset.affecran===undefined&&el.dataset.affgroupe===undefined)return;ev.stopPropagation();if(!b)return;
if(affLecture("modifier")){flash(t.refusActe.replace("{a}",t.acte_modifier),"warn");return render()}
if(el.dataset.affecran!==undefined){const v=el.dataset.affecran;if(el.checked){if(b.ecrans.indexOf(v)<0)b.ecrans.push(v)}else b.ecrans=b.ecrans.filter(x=>x!==v);render();affFocus('[data-affecran="'+v+'"]');return}
const g=affProposes()[+el.dataset.affgroupe];if(!g)return;if(el.checked)g[1].forEach(v=>{if(b.ecrans.indexOf(v)<0)b.ecrans.push(v)});else b.ecrans=b.ecrans.filter(v=>g[1].indexOf(v)<0);render();affFocus('[data-affgroupe="'+el.dataset.affgroupe+'"]')},true);
document.addEventListener("click",function(ev){if(ev.defaultPrevented)return;const el=ev.target&&ev.target.closest?ev.target.closest('[data-act^="aff-"]'):null;if(!el||el.dataset.act==="aff-set")return;ev.stopPropagation();ev.preventDefault();if(el.disabled)return;const act=el.dataset.act,b=ui.affBrouillon;
const changer=fn=>{if(!affSale())return fn();fwConfirmAsync({titre:t.affQuitterT,message:t.affQuitterM,okLabel:t.affAbandonner,danger:true}).then(x=>{if(x.ok)fn()})};
if(act==="aff-ouvrir"){const a=affichages().find(x=>x.id===el.dataset.id);if(!a||(b&&b.id===a.id))return;changer(()=>{affCharger(a,false);render();affFocus('[data-act="aff-ouvrir"][data-id="'+a.id+'"]')});return}
if(act==="aff-nouveau"){changer(()=>{affCharger({id:uid("af"),nom:t.affNouveauNom,ecrans:[]},true);render();affFocus("#affNom")});return}
if(act==="aff-annuler"){changer(()=>{affCharger(null);render()});return}
if(!b)return;
if(act==="aff-dupliquer"){changer(()=>{let nom=(b.nom+" "+t.affCopie).slice(0,60);affCharger({id:uid("af"),nom,ecrans:b.ecrans.slice()},true);render();affFocus("#affNom")});return}
if(act==="aff-niveau"){if(affLecture("modifier"))return;b.ecrans=ecransDuNiveau(el.dataset.niv);render();affFocus('[data-act="aff-niveau"][data-niv="'+el.dataset.niv+'"]');return}
if(act==="aff-monter"||act==="aff-descendre"){const v=el.dataset.v,G=affGroupeDe(v),dans=b.ecrans.filter(x=>G.indexOf(x)>=0),k=dans.indexOf(v),k2=act==="aff-monter"?k-1:k+1;if(k<0||k2<0||k2>=dans.length)return;const i=b.ecrans.indexOf(v),j=b.ecrans.indexOf(dans[k2]);[b.ecrans[i],b.ecrans[j]]=[b.ecrans[j],b.ecrans[i]];render();affFocus('[data-act="'+act+'"][data-v="'+v+'"]:not([disabled])');return}
if(act==="aff-enregistrer"){const nom=String((document.getElementById("affNom")||{}).value||b.nom||"").trim();if(!nom){flash(t.affNomReq,"err");return affFocus("#affNom")}if(/[<>]/.test(nom)){flash(t.affNomCar,"err");return affFocus("#affNom")}
if(affichages().some(x=>x.id!==b.id&&x.nom.trim().toLowerCase()===nom.toLowerCase())){flash(t.affNomDouble,"err");return affFocus("#affNom")}if(!b.ecrans.length){flash(t.affVide,"err");return}
b.nom=nom;const nv={id:b.id,nom,ecrans:b.ecrans.slice()};db.affichages=affichages().slice();const i=db.affichages.findIndex(x=>x.id===b.id);if(i>=0)db.affichages[i]=nv;else db.affichages.push(nv);ui.affOrig=JSON.stringify({nom,ecrans:nv.ecrans});save();flash(t.saved,"ok");return render()}
if(act==="aff-supprimer"){const a=affichages().find(x=>x.id===b.id);if(!a)return;const us=(db.profils||[]).filter(p=>p&&p.affichages&&(p.affichages.defaut==="aff:"+a.id||(Array.isArray(p.affichages.autorises)?p.affichages.autorises:[]).indexOf(a.id)>=0));
fwConfirmAsync({titre:t.affSupprT,message:t.affSupprM.replace("{n}",a.nom)+(us.length?" "+t.affSupprProfils.replace("{l}",us.map(p=>p.nom).join(", ")):""),okLabel:t.del,danger:true}).then(x=>{if(!x.ok)return;db.affichages=affichages().filter(y=>y.id!==a.id);(db.profils||[]).forEach(p=>{if(p&&p.affichages){if(p.affichages.defaut==="aff:"+a.id)p.affichages.defaut="";p.affichages.autorises=(Array.isArray(p.affichages.autorises)?p.affichages.autorises:[]).filter(i=>i!==a.id)}});affCharger(null);save();render()});return}
},true);
