/* correctif 41 : onglets des modules (.fw-stabs) au clavier — flèches (inversées en arabe), Début, Fin ; l'onglet atteint est activé */
document.addEventListener("keydown",function(ev){const t=ev.target;if(!t||!t.matches||!t.matches('.fw-stabs [role="tab"]'))return;const l=Array.prototype.slice.call(t.parentNode.querySelectorAll('[role="tab"]'));const rtl=document.documentElement.dir==="rtl";let i=l.indexOf(t),n;if(ev.key===(rtl?"ArrowLeft":"ArrowRight"))n=(i+1)%l.length;else if(ev.key===(rtl?"ArrowRight":"ArrowLeft"))n=(i-1+l.length)%l.length;else if(ev.key==="Home")n=0;else if(ev.key==="End")n=l.length-1;else return;ev.preventDefault();const id=l[n].id;l[n].click();setTimeout(function(){const x=id?document.getElementById(id):null;if(x)x.focus()},150)});
